import React, { useState, useMemo, useEffect } from 'react';
import ReactApexChart from 'react-apexcharts';
import { ApexOptions } from 'apexcharts';
import { motion, AnimatePresence } from 'framer-motion';
import { TelemetryPoint, StagedLap } from '../types';
import { generateSeriesColors } from '../utils/teamColors';

interface TelemetrySingleChartProps {
  title: string;
  data: TelemetryPoint[];
  dataKey: 'speed' | 'throttle' | 'brake' | 'rpm' | 'gear';
  stagedLaps: StagedLap[];
}

const TelemetrySingleChart: React.FC<TelemetrySingleChartProps> = ({
  title,
  data,
  dataKey,
  stagedLaps,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [hiddenIndices, setHiddenIndices] = useState<Set<number>>(new Set());

  // --- RESIZE HACK FIX ---
  // When opening the modal, ApexCharts often calculates dimensions before the 
  // container has finished animating/expanding, resulting in a tiny chart.
  // We force a window resize event after 300ms to trigger a re-render at the correct size.
  useEffect(() => {
      if (isExpanded) {
          const timer = setTimeout(() => {
              window.dispatchEvent(new Event('resize'));
          }, 300);
          return () => clearTimeout(timer);
      }
  }, [isExpanded, data, stagedLaps]);

  // --- 1. MEMOIZED DATA TRANSFORMATION ---
  const { series, chartColors, allColors } = useMemo(() => {
      const activeSeries: any[] = [];
      const activeColors: string[] = [];

      // Calculate Team Colors based on the StagedLaps drivers
      const baseColors = generateSeriesColors(stagedLaps.map(s => ({ team_name: s.driver.team_name })));

      stagedLaps.forEach((sl, index) => {
          if (hiddenIndices.has(index)) return;

          const traceId = `${sl.driver.name_acronym}_L${sl.lap.lap_number}`;
          const key = `${dataKey}_${traceId}`;

          const seriesData = [];
          const len = data.length;

          for(let i = 0; i < len; i++) {
              const row = data[i] as any;
              const val = row[key];
              if (val !== null && val !== undefined && row.distance !== undefined) {
                  seriesData.push([row.distance, val]);
              }
          }

          activeSeries.push({
              name: `${sl.driver.name_acronym} (L${sl.lap.lap_number})`,
              data: seriesData
          });
          activeColors.push(baseColors[index]);
      });

      return { series: activeSeries, chartColors: activeColors, allColors: baseColors };
  }, [data, stagedLaps, hiddenIndices, dataKey]);

  // --- 2. PERFORMANCE CONFIGURATION ---
  const options: ApexOptions = useMemo(() => ({
      chart: {
          type: 'line',
          animations: { enabled: false }, 
          background: 'transparent',
          fontFamily: 'Inter, sans-serif',
          toolbar: { show: isExpanded },
          zoom: { enabled: isExpanded, type: 'x', autoScaleYaxis: true },
          parentHeightOffset: 0,
          events: {
            // Optional: Also try to resize if animation frame updates
            animationEnd: () => {
                 window.dispatchEvent(new Event('resize'));
            }
          }
      },
      theme: { mode: 'dark' },
      colors: chartColors,
      fill: {
        type: 'solid',
        opacity: 1,
      },
      stroke: {
          curve: 'monotoneCubic', 
          width: 2,
      },
      grid: {
          borderColor: '#334155', 
          strokeDashArray: 3,
          xaxis: { lines: { show: false } },
          yaxis: { lines: { show: true } },
          padding: { top: 10, right: 10, bottom: 0, left: 10 }
      },
      xaxis: {
          type: 'numeric',
          tooltip: { enabled: isExpanded },
          axisBorder: { show: false },
          axisTicks: { show: false },
          labels: {
              style: { colors: '#94a3b8', fontSize: '11px', fontFamily: 'JetBrains Mono, monospace' },
              formatter: (val: string) => `${Math.round(Number(val))}m`
          }
      },
      yaxis: {
          labels: {
              style: { colors: '#94a3b8', fontSize: '11px', fontFamily: 'JetBrains Mono, monospace' },
              formatter: (val) => Math.round(Number(val)).toString(),
          },
      },
      markers: {
          size: 0,
          hover: { size: 5, strokeWidth: 0, strokeColors: '#fff' }
      },
      legend: { show: false }, 
      tooltip: {
          theme: 'dark',
          style: { fontSize: '12px', fontFamily: 'JetBrains Mono, monospace' },
          x: { formatter: (val) => `${Math.round(Number(val))}m` },
          y: { 
              formatter: (val) => {
                  const numVal = Number(val);
                  if (dataKey === 'speed') return `${Math.round(numVal)} km/h`;
                  if (dataKey === 'rpm') return `${Math.round(numVal)}`;
                  if (dataKey === 'gear') return `${numVal}`;
                  return `${Math.round(numVal)}%`;
              } 
          }
      }
  }), [chartColors, dataKey, isExpanded]);

  const toggleVisibility = (index: number) => {
      const next = new Set(hiddenIndices);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      setHiddenIndices(next);
  };

  if (!data || data.length === 0) return null;

  return (
    <>
      <div className="relative w-full h-[320px] bg-f1-surface border border-white/5 rounded-lg p-4 flex flex-col mb-6 hover:border-white/10 transition-colors shadow-lg group/chart">

        {/* HEADER: Left (Expand+Title) - Right (Legend) */}
        <div className="flex justify-between items-center mb-2 shrink-0 h-8">
            <div className="flex items-center gap-2">
                 <button 
                    onClick={() => setIsExpanded(true)}
                    className="p-1.5 rounded hover:bg-white/10 text-f1-muted hover:text-white transition-colors active:scale-95"
                    title="Expand Chart"
                >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                    </svg>
                </button>
                <h3 className="text-xs font-bold uppercase tracking-widest text-f1-muted px-1">
                    {title}
                </h3>
            </div>

            {/* INTERACTIVE LEGEND (RIGHT) */}
            <div className="flex flex-wrap gap-2">
                {stagedLaps.map((sl, index) => {
                    const isHidden = hiddenIndices.has(index);
                    const color = allColors[index];
                    return (
                        <button 
                            key={sl.id} 
                            onClick={(e) => { e.stopPropagation(); toggleVisibility(index); }}
                            className={`flex items-center gap-2 px-2 py-1 rounded border border-transparent text-[10px] font-medium transition-all active:scale-95 duration-100 ${isHidden ? 'opacity-40 grayscale bg-transparent line-through text-f1-muted' : 'bg-white/5 hover:bg-white/10 text-f1-text'}`}
                        >
                            <span className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></span>
                            <span className="uppercase">{sl.driver.name_acronym} (L{sl.lap.lap_number})</span>
                        </button>
                    );
                })}
            </div>
        </div>

        {/* CHART CONTAINER */}
        <div className="flex-1 w-full min-h-0 relative">
            <ReactApexChart 
                options={options}
                series={series}
                type="line" 
                height="100%" 
                width="100%"
            />
        </div>
      </div>

      {/* FULLSCREEN MODAL */}
      <AnimatePresence>
        {isExpanded && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
                <motion.div 
                    initial={{ opacity: 0 }} 
                    animate={{ opacity: 1 }} 
                    exit={{ opacity: 0 }}
                    onClick={() => setIsExpanded(false)}
                    className="absolute inset-0 bg-black/90 backdrop-blur-sm"
                />

                <motion.div 
                    initial={{ scale: 0.95, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    exit={{ scale: 0.95, opacity: 0 }}
                    transition={{ duration: 0.2 }}
                    className="relative w-full max-w-7xl h-[85vh] bg-[#0F1014] border border-f1-border rounded-xl p-6 shadow-2xl flex flex-col"
                >
                     <div className="flex justify-between items-center mb-6 shrink-0">
                        <div>
                             <h3 className="text-lg font-bold uppercase tracking-widest text-white">
                                {title} Analysis
                            </h3>
                             <div className="flex flex-wrap gap-3 mt-2">
                                {stagedLaps.map((sl, index) => {
                                    const isHidden = hiddenIndices.has(index);
                                    const color = allColors[index];
                                    return (
                                        <button 
                                            key={sl.id} 
                                            onClick={() => toggleVisibility(index)}
                                            className={`flex items-center gap-2 px-3 py-1.5 rounded transition-all active:scale-95 ${isHidden ? 'opacity-40 bg-white/5 line-through' : 'bg-white/10 ring-1 ring-white/10'}`}
                                        >
                                            <span className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></span>
                                            <span className="text-xs font-bold text-white uppercase">{sl.driver.name_acronym} (L{sl.lap.lap_number})</span>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                        <button 
                            onClick={() => setIsExpanded(false)}
                            className="p-3 bg-white/5 hover:bg-white/10 hover:text-white text-f1-muted rounded-full transition-all active:scale-95"
                        >
                            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                            </svg>
                        </button>
                    </div>

                    <div className="flex-1 w-full min-h-0 bg-[#0B0B0F] rounded-lg p-2 border border-white/5">
                         {/* 
                            Crucial Wrapper:
                            We ensure this container has explicit dimensions (flex-1, w-full, h-full)
                            so ApexCharts can read them when we fire the 'resize' event.
                         */}
                         <ReactApexChart 
                            options={options}
                            series={series}
                            type="line"
                            height="100%"
                            width="100%"
                         />
                    </div>
                </motion.div>
            </div>
        )}
      </AnimatePresence>
    </>
  );
};

export default React.memo(TelemetrySingleChart);

payload.text:
Agisci come un Senior React Engineer.

Dobbiamo risolvere definitivamente il problema di rendering dei grafici (`TelemetrySingleChart.tsx` e `LapHistoryChart.tsx`) che appaiono "minuscoli" o richiedono un refresh/attesa per assumere la dimensione corretta.
Il fix precedente (setTimeout) è insufficiente perché crea un ritardo visibile e non copre tutti i casi (dashboard vs modal).

Voglio implementare una soluzione basata su **`ResizeObserver`**.

**Obiettivo:**
Il grafico deve essere renderizzato SOLO quando il suo contenitore padre ha dimensioni valide (> 0). Appena il contenitore cambia dimensione (es. apertura modale, caricamento pagina), il grafico deve adattarsi istantaneamente senza "scatti" ritardati.

**Istruzioni Tecniche:**

Riscrivi il componente `components/TelemetrySingleChart.tsx` (e applica la stessa logica se necessario a `LapHistoryChart.tsx`) seguendo questo pattern:

1.  **Container Ref & State:**
    Usa un `useRef` per il contenitore `div` esterno e uno stato per tracciare se il grafico può essere mostrato (o le sue dimensioni).
    ```typescript
    const containerRef = useRef<HTMLDivElement>(null);
    const [chartSize, setChartSize] = useState<{ width: number; height: number } | null>(null);
    ```

2.  **ResizeObserver Logic:**
    Usa un `useLayoutEffect` (più veloce di useEffect per il layout) per osservare il contenitore.
    ```typescript
    useLayoutEffect(() => {
      if (!containerRef.current) return;

      const resizeObserver = new ResizeObserver((entries) => {
        if (!Array.isArray(entries) || !entries.length) return;

        const entry = entries[0];
        const { width, height } = entry.contentRect;

        // Aggiorna solo se le dimensioni sono valide e diverse
        if (width > 0 && height > 0) {
           // Usiamo requestAnimationFrame per evitare l'errore "ResizeObserver loop limit exceeded"
           requestAnimationFrame(() => {
             setChartSize({ width, height });
           });
        }
      });

      resizeObserver.observe(containerRef.current);

      return () => resizeObserver.disconnect();
    }, []);
    ```

3.  **Conditional Rendering (La Chiave):**
    Nel JSX, restituisci il componente `<Chart>` **SOLO SE** `chartSize` non è null.
    Inoltre, passa esplicitamente `width={'100%'}` e `height={'100%'}` (o le dimensioni catturate) al componente Chart.

    ```tsx
    return (
      <div ref={containerRef} className="w-full h-full min-h-[300px] relative"> {/* min-h è importante per dare struttura iniziale */}
        {chartSize ? (
          <Chart
            options={options}
            series={series}
            type="line"
            width="100%"
            height="100%" 
          />
        ) : (
           // Opzionale: Uno scheletro/loader mentre calcola le dimensioni (questione di millisecondi)
           <div className="w-full h-full flex items-center justify-center text-slate-600">Loading Chart...</div>
        )}
      </div>
    );
    ```

4.  **Pulizia:**
    Rimuovi qualsiasi vecchio `setTimeout` o hack `window.dispatchEvent` aggiunto nei passaggi precedenti. Questa soluzione li sostituisce completamente.

**Output:**
Riscrivi il codice completo di `components/TelemetrySingleChart.tsx` applicando questo pattern robusto.

