  session_key: number;
  driver_number: number;
  lap_number: number;
  date_start: string;
  lap_duration: number; // in seconds if calculated, usually null in raw stream, need 'lap_duration' from OpenF1
  is_pit_out_lap: boolean;
  duration_sector_1: number;
  duration_sector_2: number;
  duration_sector_3: number;
  segments_sector_1: number[];
  segments_sector_2: number[];
  segments_sector_3: number[];
  st_speed: number; // speed trap
}

export interface CarData {
  date: string; // ISO timestamp
  driver_number: number;
  rpm: number;
  speed: number;
  n_gear: number;
  throttle: number;
  brake: number;
  drs: number;
  meeting_key: number;
  session_key: number;
}

export interface TelemetryPoint {
  date: string; // Time relative to lap start or absolute
  distance?: number; // Calculated distance
  speed: number;
  throttle: number;
  brake: number;
  rpm: number;
  gear: number;
  drs: number;
  delta: number;
  driver: string;
  color: string;
}

export interface AIAnalysisResult {
  summary: string;
  keyInsights: string[];
  verdict: string;
}

export interface StagedLap {
  id: string; // Unique ID: driverNumber_lapNumber
  driver: Driver;
  lap: Lap;
  color: string; // Assigned Tremor color
}

import { CarData, Driver } from '../types';

export interface ProcessedCarData extends CarData {
    calculatedDistance: number;
    time: number; // Added to interface for typing
}

const STEP_SIZE = 5; // meters
const CORRELATION_SEARCH_RANGE = 60; // +/- steps (approx 300m)

// Utility: Format seconds into m:ss.ms
export const formatLapTime = (seconds: number): string => {
    const m = (seconds / 60) | 0; // Bitwise floor
    const s = (seconds % 60).toFixed(3);
    return `${m}:${s.padStart(6, '0')}`;
};

/**
 * STEP 1: Enrich raw telemetry with calculated distance, shift to start time, and clip to lap duration.
 */
const enrichAndFilter = (data: CarData[], lapStartDate: string, lapDuration: number) => {
    const len = data.length;
    if (len === 0) return null;

    const startTime = new Date(lapStartDate).getTime();
    const endTime = startTime + (lapDuration * 1000);

    const tempPoints: ProcessedCarData[] = new Array(len);
    let cumulativeDist = 0;

    for (let i = 0; i < len; i++) {
        const d = data[i];
        const tCurrent = new Date(d.date).getTime();

        if (i > 0) {
            const timeDelta = (tCurrent - tempPoints[i-1].time) / 1000;
            const vCurrent = d.speed / 3.6;
            const vPrev = data[i-1].speed / 3.6;
            const distDelta = ((vCurrent + vPrev) / 2) * timeDelta;

            if (distDelta > 0 && distDelta < 200) {
                cumulativeDist += distDelta;
            }
        }

        tempPoints[i] = {
            date: d.date,
            driver_number: d.driver_number,
            rpm: d.rpm,
            speed: d.speed,
            n_gear: d.n_gear,
            throttle: d.throttle,
            brake: d.brake,
            drs: d.drs,
            meeting_key: d.meeting_key,
            session_key: d.session_key,
            calculatedDistance: cumulativeDist,
            time: tCurrent
        };
    }

    let bestStartIdx = 0;
    let minTimeDiff = Infinity;

    for(let i = 0; i < len; i++) {
        const diff = Math.abs(tempPoints[i].time - startTime);
        if(diff < minTimeDiff) {
            minTimeDiff = diff;
            bestStartIdx = i;
        } else if (diff > minTimeDiff) {
            break; 
        }
    }

    const offset = tempPoints[bestStartIdx].calculatedDistance;

    const processed: ProcessedCarData[] = [];
    for(let i = 0; i < len; i++) {
        const p = tempPoints[i];
        if (p.time >= startTime && p.time <= endTime) {
            p.calculatedDistance = Math.max(0, p.calculatedDistance - offset);
            processed.push(p);
        }
    }

    if (processed.length < 10) return null;

    const totalDist = processed[processed.length - 1].calculatedDistance;
    return { processed, totalDist };
};

/**
 * STEP 2: Normalize distances (Rubber Banding).
 */
const normalizeDistances = (inputs: { processed: ProcessedCarData[]; totalDist: number }[]): number => {
    let totalDistSum = 0;
    const len = inputs.length;
    for (let i = 0; i < len; i++) totalDistSum += inputs[i].totalDist;

    const standardDist = totalDistSum / len;

    for (let i = 0; i < len; i++) {
        const input = inputs[i];
        const factor = standardDist / input.totalDist;
        const pts = input.processed;
        const pLen = pts.length;
        for (let j = 0; j < pLen; j++) {
            pts[j].calculatedDistance = pts[j].calculatedDistance * factor;
        }
    }
    return standardDist;
};

/**
 * STEP 3: Resample all drivers onto a standardized distance grid.
 * UPDATED: Includes TIME interpolation and DRS normalization.
 */
const resampleData = (
    inputs: { traceId: string; processed: ProcessedCarData[] }[], 
    standardDist: number
) => {
    const combined: any[] = [];
    const steps = (standardDist / STEP_SIZE) | 0;
    const numInputs = inputs.length;

    const cursors = new Int32Array(numInputs).fill(0);

    const keys = inputs.map(input => ({
        speed: `speed_${input.traceId}`,
        throttle: `throttle_${input.traceId}`,
        brake: `brake_${input.traceId}`,
        rpm: `rpm_${input.traceId}`,
        gear: `gear_${input.traceId}`,
        drs: `drs_${input.traceId}`,
        time: `time_${input.traceId}` // Internal use for Delta
    }));

    for (let i = 0; i <= steps; i++) {
        const currentDist = i * STEP_SIZE;
        const row: any = { distance: currentDist };
        let hasData = false;

        for (let idx = 0; idx < numInputs; idx++) {
            const { processed } = inputs[idx];
            const pLen = processed.length;
            let cursor = cursors[idx];

            while (cursor < pLen - 1 && processed[cursor + 1].calculatedDistance < currentDist) {
                cursor++;
            }
            cursors[idx] = cursor;

            const k = keys[idx];

            if (cursor >= pLen - 1) {
                const last = processed[pLen - 1];
                if (Math.abs(last.calculatedDistance - currentDist) < STEP_SIZE) {
                    row[k.speed] = Math.round(last.speed);
                    row[k.throttle] = Math.round(last.throttle);
                    row[k.brake] = Math.round(last.brake);
                    row[k.rpm] = Math.round(last.rpm);
                    row[k.gear] = last.n_gear;
                    // DRS Logic: > 9 is OPEN (1), else CLOSED (0)
                    row[k.drs] = last.drs > 9 ? 1 : 0;
                    row[k.time] = last.time;
                    hasData = true;
                } else {
                    row[k.speed] = null;
                }
                continue;
            }

            const p1 = processed[cursor];
            const p2 = processed[cursor + 1];
            const segmentLen = p2.calculatedDistance - p1.calculatedDistance;

            if (segmentLen > 0) {
                const ratio = (currentDist - p1.calculatedDistance) / segmentLen;

                row[k.speed] = Math.round(p1.speed + (p2.speed - p1.speed) * ratio);
                row[k.throttle] = Math.round(p1.throttle + (p2.throttle - p1.throttle) * ratio);
                row[k.brake] = Math.round(p1.brake + (p2.brake - p1.brake) * ratio);
                row[k.rpm] = Math.round(p1.rpm + (p2.rpm - p1.rpm) * ratio);

                // Gear: Nearest Neighbor
                row[k.gear] = ratio < 0.5 ? p1.n_gear : p2.n_gear;

                // DRS: Step Logic (Nearest Neighbor prevents 0.5 DRS)
                const drsVal = ratio < 0.5 ? p1.drs : p2.drs;
                row[k.drs] = drsVal > 9 ? 1 : 0;

                // Time: Linear Interpolation (Critical for Delta)
                row[k.time] = p1.time + (p2.time - p1.time) * ratio;

                hasData = true;
            }
        }

        if (hasData) combined.push(row);
    }
    return combined;
};

/**
 * STEP 4: Align data.
 * UPDATED: Includes shifting 'time' and 'drs' columns.
 */
const alignAndTrim = (combinedData: any[], traceIds: string[]) => {
    if (traceIds.length < 2 || combinedData.length === 0) return combinedData;

    const refTrace = traceIds[0];
    const refKey = `speed_${refTrace}`;
    const dataLen = combinedData.length;

    const refSpeed = new Float32Array(dataLen);
    for(let i=0; i<dataLen; i++) refSpeed[i] = Number(combinedData[i][refKey]) || 0;

    const alignedData = new Array(dataLen);
    for(let i=0; i<dataLen; i++) alignedData[i] = { ...combinedData[i] };

    for (let i = 1; i < traceIds.length; i++) {
        const traceId = traceIds[i];
        const targetKey = `speed_${traceId}`;

        const targetSpeed = new Float32Array(dataLen);
        for(let k=0; k<dataLen; k++) targetSpeed[k] = Number(combinedData[k][targetKey]) || 0;

        let minMSE = Infinity;
        let bestShift = 0;

        for (let shift = -CORRELATION_SEARCH_RANGE; shift <= CORRELATION_SEARCH_RANGE; shift++) {
            let sumSqDiff = 0;
            let count = 0;

            const start = shift < 0 ? -shift : 0;
            const end = shift > 0 ? dataLen - shift : dataLen;

            for (let j = start; j < end; j++) {
                const diff = refSpeed[j] - targetSpeed[j + shift];
                sumSqDiff += diff * diff;
                count++;
            }

            if (count > (dataLen >> 1)) {
                const mse = sumSqDiff / count;
                if (mse < minMSE) {
                    minMSE = mse;
                    bestShift = shift;
                }
            }
        }

        if (bestShift !== 0) {
            // Include new fields in shift
            const keysToShift = [
                `speed_${traceId}`, `throttle_${traceId}`, 
                `brake_${traceId}`, `rpm_${traceId}`, `gear_${traceId}`,
                `drs_${traceId}`, `time_${traceId}`
            ];

            for (let j = 0; j < dataLen; j++) {
                const sourceIdx = j + bestShift;
                const row = alignedData[j];

                if (sourceIdx >= 0 && sourceIdx < dataLen) {
                    const srcRow = combinedData[sourceIdx];
                    for (const key of keysToShift) row[key] = srcRow[key];
                } else {
                    for (const key of keysToShift) row[key] = null;
                }
            }
        }
    }

    let startIndex = 0;
    let endIndex = dataLen - 1;

    for (let i = 0; i < dataLen; i++) {
        let allValid = true;
        const row = alignedData[i];
        for (const tId of traceIds) {
            if (row[`speed_${tId}`] == null) {
                allValid = false;
                break;
            }
        }
        if (allValid) {
            startIndex = i;
            break;
        }
    }

    for (let i = dataLen - 1; i >= 0; i--) {
        let allValid = true;
        const row = alignedData[i];
        for (const tId of traceIds) {
            if (row[`speed_${tId}`] == null) {
                allValid = false;
                break;
            }
        }
        if (allValid) {
            endIndex = i;
            break;
        }
    }

    if (startIndex > endIndex) return [];

    const trimmed = alignedData.slice(startIndex, endIndex + 1);
    const distanceOffset = trimmed[0].distance;
    const tLen = trimmed.length;

    for (let i = 0; i < tLen; i++) {
        trimmed[i].distance -= distanceOffset;
    }

    return trimmed;
};

/**
 * STEP 5: Calculate Delta to Fastest Lap
 * Finds the reference lap (min time at last index) and calculates time diff for all others.
 */
const calculateDeltas = (data: any[], traceIds: string[]) => {
    if (data.length === 0 || traceIds.length === 0) return data;

    // Find Reference Trace (Fastest cumulative time at the end)
    let refId = traceIds[0];
    let minTotalTime = Infinity;
    const lastRow = data[data.length - 1];

    for (const id of traceIds) {
        const t = lastRow[`time_${id}`];
        if (t !== undefined && t !== null && t < minTotalTime) {
            minTotalTime = t;
            refId = id;
        }
    }

    // Calculate Delta for each row
    const len = data.length;
    for (let i = 0; i < len; i++) {
        const row = data[i];
        const refTime = row[`time_${refId}`];

        for (const id of traceIds) {
            const targetTime = row[`time_${id}`];
            if (refTime !== undefined && refTime !== null && targetTime !== undefined && targetTime !== null) {
                // Delta = DriverTime - RefTime
                // Positive = Slower, Negative = Faster
                row[`delta_${id}`] = (targetTime - refTime) / 1000; // Convert ms to seconds
            } else {
                row[`delta_${id}`] = null;
            }
        }
    }
    return data;
};

export const processTelemetryData = (
    inputs: { driver: Driver; data: CarData[]; lapStartDate: string; lapDuration: number; traceId: string }[]
) => {
    // 1. Enrich & Filter
    const enrichedInputs: { traceId: string; processed: ProcessedCarData[]; totalDist: number; driver: Driver }[] = [];

    for (const input of inputs) {
        const result = enrichAndFilter(input.data, input.lapStartDate, input.lapDuration);
        if (result) {
            enrichedInputs.push({ traceId: input.traceId, driver: input.driver, ...result });
        }
    }

    if (enrichedInputs.length === 0) return [];

    // 2. Normalize
    const standardDist = normalizeDistances(enrichedInputs);

    // 3. Resample
    const combined = resampleData(enrichedInputs, standardDist);

    // 4. Align & Trim
    const aligned = alignAndTrim(combined, enrichedInputs.map(i => i.traceId));

    // 5. Calculate Deltas
    return calculateDeltas(aligned, enrichedInputs.map(i => i.traceId));
};

import React, { useState, useMemo, useRef, useLayoutEffect } from 'react';
import ReactApexChart from 'react-apexcharts';
import { ApexOptions, ApexAxisChartSeries } from 'apexcharts';
import { motion, AnimatePresence } from 'framer-motion';
import { TelemetryPoint, StagedLap } from '../types';
import { generateSeriesColors } from '../utils/teamColors';

// --- INTERNAL COMPONENT: RESPONSIVE CHART WRAPPER ---
const ResponsiveApexChart: React.FC<{
    options: ApexOptions;
    series: ApexAxisChartSeries;
    type: "line" | "area" | "bar";
    className?: string;
}> = ({ options, series, type, className }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [shouldRender, setShouldRender] = useState(false);

    useLayoutEffect(() => {
        if (!containerRef.current) return;

        const resizeObserver = new ResizeObserver((entries) => {
            if (!Array.isArray(entries) || !entries.length) return;

            const entry = entries[0];
            const { width, height } = entry.contentRect;

            if (width > 0 && height > 0) {
                requestAnimationFrame(() => {
                    setShouldRender(true);
                });
            }
        });

        resizeObserver.observe(containerRef.current);

        return () => resizeObserver.disconnect();
    }, []);

    return (
        <div ref={containerRef} className={`w-full h-full relative min-h-[50px] ${className || ''}`}>
            {shouldRender ? (
                <ReactApexChart
                    options={options}
                    series={series}
                    type={type}
                    height="100%"
                    width="100%"
                />
            ) : (
                <div className="absolute inset-0 flex items-center justify-center opacity-30">
                     <div className="w-6 h-6 border-2 border-f1-red border-t-transparent rounded-full animate-spin"></div>
                </div>
            )}
        </div>
    );
};

interface TelemetrySingleChartProps {
  title: string;
  data: TelemetryPoint[];
  dataKey: 'speed' | 'throttle' | 'brake' | 'rpm' | 'gear' | 'drs' | 'delta';
  stagedLaps: StagedLap[];
}

const TelemetrySingleChart: React.FC<TelemetrySingleChartProps> = ({
  title,
  data,
  dataKey,
  stagedLaps,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [hiddenIndices, setHiddenIndices] = useState<Set<number>>(new Set());

  // --- MEMOIZED DATA TRANSFORMATION ---
  const { series, chartColors, allColors } = useMemo(() => {
      const activeSeries: any[] = [];
      const activeColors: string[] = [];

      const baseColors = generateSeriesColors(stagedLaps.map(s => ({ team_name: s.driver.team_name })));

      stagedLaps.forEach((sl, index) => {
          if (hiddenIndices.has(index)) return;

          const traceId = `${sl.driver.name_acronym}_L${sl.lap.lap_number}`;
          const key = `${dataKey}_${traceId}`;

          const seriesData = [];
          const len = data.length;

          for(let i = 0; i < len; i++) {
              const row = data[i] as any;
              const val = row[key];
              if (val !== null && val !== undefined && row.distance !== undefined) {
                  seriesData.push([row.distance, val]);
              }
          }

          activeSeries.push({
              name: `${sl.driver.name_acronym} (L${sl.lap.lap_number})`,
              data: seriesData
          });
          activeColors.push(baseColors[index]);
      });

      return { series: activeSeries, chartColors: activeColors, allColors: baseColors };
  }, [data, stagedLaps, hiddenIndices, dataKey]);

  // --- PERFORMANCE CONFIGURATION ---
  const options: ApexOptions = useMemo(() => {
      // Logic for Stroke Curve: Step line for DRS/Gear, Monotone for others
      const curveType = (dataKey === 'drs' || dataKey === 'gear') ? 'stepline' : 'monotoneCubic';

      // Logic for Y-Axis Formatting
      const yAxisFormatter = (val: number) => {
          if (dataKey === 'drs') return val === 1 ? 'OPEN' : 'CLSD';
          if (dataKey === 'delta') return `${val > 0 ? '+' : ''}${val.toFixed(3)}s`;
          return Math.round(Number(val)).toString();
      };

      // Logic for Tooltip Formatting
      const tooltipFormatter = (val: number) => {
          const numVal = Number(val);
          if (dataKey === 'speed') return `${Math.round(numVal)} km/h`;
          if (dataKey === 'rpm') return `${Math.round(numVal)}`;
          if (dataKey === 'gear') return `${numVal}`;
          if (dataKey === 'throttle' || dataKey === 'brake') return `${Math.round(numVal)}%`;
          if (dataKey === 'drs') return numVal === 1 ? 'OPEN' : 'CLOSED';
          if (dataKey === 'delta') return `${numVal > 0 ? '+' : ''}${numVal.toFixed(3)}s`;
          return `${numVal}`;
      };

      return {
        chart: {
            type: 'line',
            animations: { enabled: false }, 
            background: 'transparent',
            fontFamily: 'Inter, sans-serif',
            toolbar: { show: isExpanded },
            zoom: { enabled: isExpanded, type: 'x', autoScaleYaxis: true },
            parentHeightOffset: 0,
        },
        theme: { mode: 'dark' },
        colors: chartColors,
        fill: {
            type: 'solid',
            opacity: 1,
        },
        stroke: {
            curve: curveType, 
            width: 2,
        },
        grid: {
            borderColor: '#334155', 
            strokeDashArray: 3,
            xaxis: { lines: { show: false } },
            yaxis: { lines: { show: true } },
            padding: { top: 10, right: 10, bottom: 0, left: 10 }
        },
        xaxis: {
            type: 'numeric',
            tooltip: { enabled: isExpanded },
            axisBorder: { show: false },
            axisTicks: { show: false },
            labels: {
                style: { colors: '#94a3b8', fontSize: '11px', fontFamily: 'JetBrains Mono, monospace' },
                formatter: (val: string) => `${Math.round(Number(val))}m`
            }
        },
        yaxis: {
            labels: {
                style: { colors: '#94a3b8', fontSize: '11px', fontFamily: 'JetBrains Mono, monospace' },
                formatter: yAxisFormatter,
            },
            // For DRS, fix the range to 0-1 nicely
            min: dataKey === 'drs' ? 0 : undefined,
            max: dataKey === 'drs' ? 1.1 : undefined,
            tickAmount: dataKey === 'drs' ? 1 : undefined, // Only 2 ticks (0 and 1) approx
        },
        markers: {
            size: 0,
            hover: { size: 5, strokeWidth: 0, strokeColors: '#fff' }
        },
        legend: { show: false }, 
        tooltip: {
            theme: 'dark',
            style: { fontSize: '12px', fontFamily: 'JetBrains Mono, monospace' },
            x: { formatter: (val) => `${Math.round(Number(val))}m` },
            y: { formatter: tooltipFormatter }
        }
    }
  }, [chartColors, dataKey, isExpanded]);

  const toggleVisibility = (index: number) => {
      const next = new Set(hiddenIndices);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      setHiddenIndices(next);
  };

  if (!data || data.length === 0) return null;

  return (
    <>
      <div className="relative w-full h-[320px] bg-f1-surface border border-white/5 rounded-lg p-4 flex flex-col mb-6 hover:border-white/10 transition-colors shadow-lg group/chart">

        {/* HEADER */}
        <div className="flex justify-between items-center mb-2 shrink-0 h-8">
            <div className="flex items-center gap-2">
                 <button 
                    onClick={() => setIsExpanded(true)}
                    className="p-1.5 rounded hover:bg-white/10 text-f1-muted hover:text-white transition-colors active:scale-95"
                    title="Expand Chart"
                >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                    </svg>
                </button>
                <h3 className="text-xs font-bold uppercase tracking-widest text-f1-muted px-1">
                    {title}
                </h3>
            </div>

            <div className="flex flex-wrap gap-2">
                {stagedLaps.map((sl, index) => {
                    const isHidden = hiddenIndices.has(index);
                    const color = allColors[index];
                    return (
                        <button 
                            key={sl.id} 
                            onClick={(e) => { e.stopPropagation(); toggleVisibility(index); }}
                            className={`flex items-center gap-2 px-2 py-1 rounded border border-transparent text-[10px] font-medium transition-all active:scale-95 duration-100 ${isHidden ? 'opacity-40 grayscale bg-transparent line-through text-f1-muted' : 'bg-white/5 hover:bg-white/10 text-f1-text'}`}
                        >
                            <span className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></span>
                            <span className="uppercase">{sl.driver.name_acronym} (L{sl.lap.lap_number})</span>
                        </button>
                    );
                })}
            </div>
        </div>

        {/* CHART CONTAINER */}
        <div className="flex-1 w-full min-h-0 relative">
            <ResponsiveApexChart 
                options={options}
                series={series}
                type="line"
            />
        </div>
      </div>

      {/* FULLSCREEN MODAL */}
      <AnimatePresence>
        {isExpanded && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
                <motion.div 
                    initial={{ opacity: 0 }} 
                    animate={{ opacity: 1 }} 
                    exit={{ opacity: 0 }}
                    onClick={() => setIsExpanded(false)}
                    className="absolute inset-0 bg-black/90 backdrop-blur-sm"
                />

                <motion.div 
                    initial={{ scale: 0.95, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    exit={{ scale: 0.95, opacity: 0 }}
                    transition={{ duration: 0.2 }}
                    className="relative w-full max-w-7xl h-[85vh] bg-[#0F1014] border border-f1-border rounded-xl p-6 shadow-2xl flex flex-col"
                >
                     <div className="flex justify-between items-center mb-6 shrink-0">
                        <div>
                             <h3 className="text-lg font-bold uppercase tracking-widest text-white">
                                {title} Analysis
                            </h3>
                             <div className="flex flex-wrap gap-3 mt-2">
                                {stagedLaps.map((sl, index) => {
                                    const isHidden = hiddenIndices.has(index);
                                    const color = allColors[index];
                                    return (
                                        <button 
                                            key={sl.id} 
                                            onClick={() => toggleVisibility(index)}
                                            className={`flex items-center gap-2 px-3 py-1.5 rounded transition-all active:scale-95 ${isHidden ? 'opacity-40 bg-white/5 line-through' : 'bg-white/10 ring-1 ring-white/10'}`}
                                        >
                                            <span className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></span>
                                            <span className="text-xs font-bold text-white uppercase">{sl.driver.name_acronym} (L{sl.lap.lap_number})</span>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                        <button 
                            onClick={() => setIsExpanded(false)}
                            className="p-3 bg-white/5 hover:bg-white/10 hover:text-white text-f1-muted rounded-full transition-all active:scale-95"
                        >
                            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                            </svg>
                        </button>
                    </div>

                    <div className="flex-1 w-full min-h-0 bg-[#0B0B0F] rounded-lg p-2 border border-white/5">
                         <ResponsiveApexChart 
                            options={options}
                            series={series}
                            type="line"
                         />
                    </div>
                </motion.div>
            </div>
        )}
      </AnimatePresence>
    </>
  );
};

export default React.memo(TelemetrySingleChart);

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { getSessions, getDrivers, getLaps, getCarTelemetry, getLatestSession } from './services/openf1Service';
import { analyzeTelemetry } from './services/geminiService';
import { Session, Driver, Lap, AIAnalysisResult, StagedLap } from './types';
import SessionSelector from './components/SessionSelector';
import TelemetrySingleChart from './components/TelemetrySingleChart';
import AIAnalysis from './components/AIAnalysis';
import LapHistoryChart from './components/LapHistoryChart';
import DriverSelector from './components/DriverSelector';
import { processTelemetryData, formatLapTime } from './utils/telemetryUtils';
import { getTeamColors } from './utils/teamColors';
import { FALLBACK_COLOR } from './utils/chartUtils';

// --- CONSTANTS ---
const CURRENT_YEAR = new Date().getFullYear();
const START_YEAR = 2023;
const AVAILABLE_YEARS = Array.from({ length: CURRENT_YEAR - START_YEAR + 1 }, (_, i) => CURRENT_YEAR - i);
const MAX_LAPS = 8;

export const App: React.FC = () => {
  // --- STATE ---
  const [selectedYear, setSelectedYear] = useState<number>(CURRENT_YEAR);
  const [sessions, setSessions] = useState<Session[]>([]);
  const [selectedSession, setSelectedSession] = useState<Session | null>(null);

  const [allDrivers, setAllDrivers] = useState<Driver[]>([]);
  const [selectedDrivers, setSelectedDrivers] = useState<Driver[]>([]);

  const pendingRandomCountRef = useRef<number | null>(null);
  const [isRandomizing, setIsRandomizing] = useState(false);

  // Data Containers
  const [lapsData, setLapsData] = useState<Map<number, Lap[]>>(new Map());
  const [stagedLaps, setStagedLaps] = useState<StagedLap[]>([]);
  const [telemetryData, setTelemetryData] = useState<any[]>([]);

  // Loading States
  const [loadingLaps, setLoadingLaps] = useState(false);
  const [loadingTelemetry, setLoadingTelemetry] = useState(false);
  const [loadingSessions, setLoadingSessions] = useState(false);

  const [aiResult, setAiResult] = useState<AIAnalysisResult | null>(null);
  const [analyzing, setAnalyzing] = useState(false);

  // --- INITIALIZATION ---
  useEffect(() => {
    let mounted = true;
    const init = async () => {
        setLoadingSessions(true);
        try {
            const latest = await getLatestSession();
            if(!mounted) return;

            if(latest) {
                setSelectedYear(latest.year);
                const allSessions = await getSessions(latest.year);
                if(mounted) {
                    setSessions(allSessions);
                    setSelectedSession(latest);
                }
            } else {
                const allSessions = await getSessions(selectedYear);
                if(mounted) setSessions(allSessions);
            }
        } catch (e) {
            console.error("Init Error", e);
        } finally {
            if(mounted) setLoadingSessions(false);
        }
    };
    init();
    return () => { mounted = false; };
  }, []);

  // --- DRIVER LOADING ---
  useEffect(() => {
    if (!selectedSession) return;
    let mounted = true;
    const loadDrivers = async () => {
        try {
            const d = await getDrivers(selectedSession.session_key);
            if (mounted) {
                const unique = d.filter((v, i, a) => a.findIndex(t => (t.driver_number === v.driver_number)) === i);
                setAllDrivers(unique);

                if (pendingRandomCountRef.current !== null) {
                    const count = pendingRandomCountRef.current;
                    const shuffled = [...unique].sort(() => 0.5 - Math.random());
                    setSelectedDrivers(shuffled.slice(0, count));
                    pendingRandomCountRef.current = null;
                } else {
                    setSelectedDrivers([]);
                }
                setLapsData(new Map());
                setStagedLaps([]);
                setTelemetryData([]);
            }
        } catch (e) { console.error(e); }
    };
    loadDrivers();
    return () => { mounted = false; };
  }, [selectedSession]);

  // --- HANDLERS ---
  const handleYearChange = async (year: number) => {
      if(year === selectedYear) return;
      setSelectedYear(year);
      setLoadingSessions(true);
      setSelectedSession(null);
      setSessions([]);

      try {
          const newSessions = await getSessions(year);
          setSessions(newSessions);
          if (newSessions.length > 0) setSelectedSession(newSessions[0]);
      } catch (e) { console.error(e); } 
      finally { setLoadingSessions(false); }
  };

  const handleRefreshSessions = async () => {
      setLoadingSessions(true);
      try {
          const freshSessions = await getSessions(selectedYear);
          setSessions(freshSessions);
          if (selectedSession) {
              const stillExists = freshSessions.find(s => s.session_key === selectedSession.session_key);
              if (stillExists) setSelectedSession(stillExists);
          } else if (freshSessions.length > 0) {
               setSelectedSession(freshSessions[0]);
          }
      } catch (e) { console.error(e); } 
      finally { setLoadingSessions(false); }
  };

  const handleToggleDriver = (driver: Driver) => {
      const exists = selectedDrivers.find(d => d.driver_number === driver.driver_number);
      if (exists) {
          setSelectedDrivers(prev => prev.filter(d => d.driver_number !== driver.driver_number));
          setLapsData(prev => {
              const next = new Map(prev);
              next.delete(driver.driver_number);
              return next;
          });
          setStagedLaps(prev => prev.filter(sl => sl.driver.driver_number !== driver.driver_number));
      } else {
          if (selectedDrivers.length < 6) setSelectedDrivers(prev => [...prev, driver]);
      }
  };

  const loadLapHistory = useCallback(async () => {
      if (!selectedSession || selectedDrivers.length === 0) return;
      setLoadingLaps(true);
      const newLapsMap = new Map<number, Lap[]>();
      try {
          await Promise.all(selectedDrivers.map(async (d) => {
              const laps = await getLaps(selectedSession.session_key, d.driver_number);
              const validLaps = laps.filter(l => l.lap_duration > 0);
              newLapsMap.set(d.driver_number, validLaps);
          }));
          setLapsData(newLapsMap);
          setStagedLaps([]); 
      } catch (e) { console.error(e); } 
      finally { setLoadingLaps(false); }
  }, [selectedSession, selectedDrivers]);

  useEffect(() => {
      if (isRandomizing && selectedDrivers.length > 0) {
          loadLapHistory();
          setIsRandomizing(false);
      }
  }, [selectedDrivers, isRandomizing, loadLapHistory]);

  const syncTelemetry = async () => {
      if (!selectedSession || stagedLaps.length === 0) return;
      setLoadingTelemetry(true);
      setAiResult(null);

      try {
          const inputs = await Promise.all(stagedLaps.map(async (sl) => {
              const { driver, lap } = sl;
              const buffer = 1.5; 
              const data = await getCarTelemetry(
                  selectedSession.session_key, 
                  driver.driver_number, 
                  new Date(new Date(lap.date_start).getTime() - 1500).toISOString(), 
                  new Date(new Date(lap.date_start).getTime() + (lap.lap_duration + buffer) * 1000).toISOString()
              );
              const traceId = `${driver.name_acronym}_L${lap.lap_number}`;
              return { driver, data, lapStartDate: lap.date_start, lapDuration: lap.lap_duration, traceId };
          }));

          const validInputs = inputs.filter(i => i.data && i.data.length > 0);
          if (validInputs.length > 0) {
              const processed = processTelemetryData(validInputs);
              setTelemetryData(processed);
          }
      } catch(e) { console.error(e); } 
      finally { setLoadingTelemetry(false); }
  };

  const handleRandomize = useCallback(async () => {
      setLoadingSessions(true);
      setSelectedDrivers([]); 
      setLapsData(new Map());
      setStagedLaps([]);
      setTelemetryData([]);
      setIsRandomizing(true);
      try {
          const randomYear = AVAILABLE_YEARS[Math.floor(Math.random() * AVAILABLE_YEARS.length)];
          const allSessions = await getSessions(randomYear);
          const qualifyingSessions = allSessions.filter(s => s.session_name === 'Qualifying');

          if (qualifyingSessions.length === 0) {
             setLoadingSessions(false); setIsRandomizing(false); return;
          }

          const randomSession = qualifyingSessions[Math.floor(Math.random() * qualifyingSessions.length)];
          const count = Math.floor(Math.random() * 3) + 2; 

          pendingRandomCountRef.current = count;
          setSelectedYear(randomYear);
          setSessions(allSessions);
          setSelectedSession(randomSession);

      } catch (e) {
          console.error(e); setIsRandomizing(false);
      } finally { setLoadingSessions(false); }
  }, []);

  const stagePBLaps = () => {
      const newStaged = [...stagedLaps];
      selectedDrivers.forEach(d => {
          if (newStaged.length >= MAX_LAPS) return;
          const laps = lapsData.get(d.driver_number) || [];
          if (laps.length > 0) {
              const pb = [...laps].sort((a,b) => a.lap_duration - b.lap_duration)[0];
              const id = `${d.driver_number}_${pb.lap_number}`;
              if (!newStaged.find(s => s.id === id)) {
                   newStaged.push({ id, driver: d, lap: pb, color: '' });
              }
          }
      });
      setStagedLaps(newStaged);
  };

  const handleToggleLap = useCallback((driver: Driver, lap: Lap) => {
      const id = `${driver.driver_number}_${lap.lap_number}`;

      setStagedLaps(prev => {
          const existsIdx = prev.findIndex(s => s.id === id);

          if (existsIdx >= 0) {
              const newStaged = [...prev];
              newStaged.splice(existsIdx, 1);
              return newStaged;
          } else {
              if (prev.length < MAX_LAPS) {
                 setTimeout(() => {
                    const el = document.getElementById(`staged-lap-${id}`);
                    if (el && typeof el.scrollIntoView === 'function') {
                        el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                    }
                 }, 100);

                 return [...prev, { id, driver, lap, color: '' }];
              }
              return prev;
          }
      });
  }, []);

  const fetchAIAnalysis = async () => {
    if (stagedLaps.length === 0 || telemetryData.length === 0) return;
    setAnalyzing(true);
    try {
        const aiSampleRate = Math.max(1, Math.floor(telemetryData.length / 50));
        const colors = getTeamColors(stagedLaps.map(s => s.driver));

        const inputs = stagedLaps.map((sl, index) => {
            const { driver, lap } = sl;
            const traceId = `${driver.name_acronym}_L${lap.lap_number}`;
            const formattedT = telemetryData
                .filter((_, i) => i % aiSampleRate === 0)
                .map(row => ({
                    date: '', distance: row.distance,
                    speed: row[`speed_${traceId}`] || 0,
                    throttle: row[`throttle_${traceId}`] || 0,
                    brake: row[`brake_${traceId}`] || 0,
                    rpm: row[`rpm_${traceId}`] || 0,
                    gear: row[`gear_${traceId}`] || 0,
                    drs: row[`drs_${traceId}`] || 0,
                    delta: row[`delta_${traceId}`] || 0,
                    driver: driver.name_acronym, color: colors[index]
                }));
            return { driver, lap, telemetry: formattedT, label: `${driver.name_acronym} (L${lap.lap_number})` };
        });

        const res = await analyzeTelemetry(inputs);
        setAiResult(res);
    } catch (error) { console.error(error); } 
    finally { setAnalyzing(false); }
  };

  const isHistorySynced = useMemo(() => {
      if (loadingLaps || selectedDrivers.length === 0) return false;
      return selectedDrivers.every(d => lapsData.has(d.driver_number) && (lapsData.get(d.driver_number)?.length || 0) > 0);
  }, [selectedDrivers, lapsData, loadingLaps]);

  const allTelemetryColors = useMemo(() => 
    getTeamColors(stagedLaps.map(s => s.driver)), 
  [stagedLaps]);

  return (
    <div className="min-h-screen w-full bg-[#09090b] text-white font-sans flex flex-col overflow-x-hidden selection:bg-f1-red/30">
        <header className="sticky top-0 z-50 w-full bg-[#09090b] border-b border-white/5 px-6 py-4 flex items-center justify-between shadow-md">
            <div className="flex items-center gap-3">
                <div className="w-8 h-8 bg-f1-red rounded-sm flex items-center justify-center shadow-[0_0_15px_rgba(255,30,0,0.5)]">
                    <span className="font-mono font-bold text-white text-lg">S</span>
                </div>
                <div className="flex flex-col leading-none">
                     <h1 className="font-sans text-xl font-bold tracking-tight text-white uppercase">StintLogic<span className="text-f1-red">.com</span></h1>
                     <span className="text-[9px] text-f1-muted uppercase tracking-[0.25em]">Telemetry Lab</span>
                </div>
            </div>
        </header>

        <main className="flex-1 w-full p-6 space-y-6 bg-[#09090b] bg-[radial-gradient(#ffffff08_1px,#09090b_1px)] [background-size:20px_20px]">
            <div className="container mx-auto">
                <SessionSelector 
                    years={AVAILABLE_YEARS} selectedYear={selectedYear} onSelectYear={handleYearChange}
                    sessions={sessions} selectedSession={selectedSession} onSelectSession={setSelectedSession}
                    isLoading={loadingSessions} onRandomize={handleRandomize} onRefresh={handleRefreshSessions}
                />

                <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 mb-8">
                    <aside className="lg:col-span-1 space-y-8">
                        <div>
                            <h2 className="text-xs font-bold uppercase tracking-widest text-f1-muted mb-4 flex items-center gap-2">
                                 <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
                                 Driver Selection
                            </h2>
                            <DriverSelector 
                                allDrivers={allDrivers}
                                selectedDrivers={selectedDrivers}
                                onToggleDriver={handleToggleDriver}
                                maxSelection={6}
                            />
                        </div>

                        {isHistorySynced && !loadingLaps ? (
                             <div className="w-full py-4 px-4 bg-emerald-500/5 border border-emerald-500/20 rounded-lg flex items-center justify-center gap-3 shadow-lg">
                                <span className="relative flex h-2 w-2">
                                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                                    <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
                                </span>
                                <span className="text-[10px] font-bold text-emerald-400 uppercase tracking-widest">History Synced</span>
                            </div>
                        ) : (
                            <button 
                                onClick={loadLapHistory}
                                disabled={selectedDrivers.length === 0 || loadingLaps}
                                className={`w-full py-4 font-bold text-xs uppercase tracking-widest rounded-lg shadow-lg disabled:opacity-50 transition-all duration-200 active:scale-95 flex items-center justify-center gap-2
                                    ${loadingLaps 
                                        ? 'bg-white/5 border border-white/10 text-f1-muted cursor-wait' 
                                        : 'bg-f1-red text-white hover:bg-red-600 hover:shadow-[0_0_20px_rgba(220,38,38,0.4)]'
                                    }`}
                            >
                                {loadingLaps ? 'FETCHING...' : 'SYNC LAP HISTORY'}
                            </button>
                        )}
                    </aside>

                    <div className="lg:col-span-3">
                        {lapsData.size > 0 && selectedDrivers.length > 0 ? (
                            <div className="space-y-6">
                                <LapHistoryChart 
                                    selectedDrivers={selectedDrivers}
                                    lapsData={lapsData}
                                    stagedLaps={stagedLaps}
                                    onToggleLap={handleToggleLap}
                                    colors={[]} 
                                />

                                <div className="bg-[#121218] border border-white/5 p-6 rounded-lg shadow-2xl relative overflow-hidden">
                                    <div className="flex justify-between items-center mb-6 relative z-10">
                                        <div>
                                            <h3 className="text-xs font-bold uppercase tracking-widest text-white mb-1">Telemetry Inputs</h3>
                                            <span className="text-[10px] text-f1-muted">Comparing {stagedLaps.length}/{MAX_LAPS} laps</span>
                                        </div>
                                        <div className="flex gap-2">
                                            <button 
                                                onClick={() => setStagedLaps([])} 
                                                disabled={stagedLaps.length === 0}
                                                className="px-3 py-1.5 text-[10px] font-bold uppercase text-f1-muted hover:text-white transition-colors disabled:opacity-30"
                                            >
                                                Reset
                                            </button>
                                            <button 
                                                onClick={stagePBLaps} 
                                                disabled={stagedLaps.length >= MAX_LAPS}
                                                className="px-4 py-2 bg-white/5 text-white text-[10px] font-bold uppercase rounded hover:bg-white/10 transition-all active:scale-95 disabled:opacity-50 border border-white/10"
                                            >
                                                + Add Fastest Laps
                                            </button>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6 relative z-10">
                                        <AnimatePresence>
                                            {stagedLaps.map((sl, index) => {
                                                const teamColor = allTelemetryColors[index] || FALLBACK_COLOR.primary;
                                                return (
                                                    <motion.div
                                                        key={sl.id}
                                                        id={`staged-lap-${sl.id}`}
                                                        initial={{ opacity: 0, y: 10 }}
                                                        animate={{ opacity: 1, y: 0 }}
                                                        exit={{ opacity: 0, scale: 0.9 }}
                                                        className="relative bg-white/5 border border-white/5 p-3 rounded group hover:border-white/20 transition-all cursor-pointer"
                                                        onClick={() => handleToggleLap(sl.driver, sl.lap)}
                                                    >
                                                        <div className={`absolute left-0 top-0 bottom-0 w-1 rounded-l`} style={{ backgroundColor: teamColor }}></div>
                                                        <div className="pl-3">
                                                            <div className="flex justify-between">
                                                                <div className="text-[10px] text-f1-muted font-bold uppercase">{sl.driver.name_acronym}</div>
                                                                <div className="text-[9px] text-f1-muted">L{sl.lap.lap_number}</div>
                                                            </div>
                                                            <div className="text-sm font-mono text-white font-bold tracking-tight">{formatLapTime(sl.lap.lap_duration)}</div>
                                                        </div>
                                                    </motion.div>
                                                );
                                            })}
                                        </AnimatePresence>
                                        {stagedLaps.length === 0 && (
                                            <div className="col-span-full h-24 border-2 border-dashed border-slate-800 rounded-lg flex items-center justify-center bg-transparent">
                                                <span className="text-slate-600 font-mono text-xs uppercase tracking-[0.2em] font-medium">Select Laps from History to Compare Telemetry</span>
                                            </div>
                                        )}
                                    </div>

                                    <button 
                                        onClick={syncTelemetry}
                                        disabled={stagedLaps.length === 0 || loadingTelemetry}
                                        className="w-full py-3 bg-blue-600 text-white text-xs font-bold uppercase tracking-widest rounded shadow-[0_0_15px_rgba(37,99,235,0.3)] hover:bg-blue-500 hover:shadow-[0_0_25px_rgba(37,99,235,0.5)] transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none disabled:active:scale-100 relative z-10"
                                    >
                                        {loadingTelemetry ? 'PROCESSING...' : 'ANALYZE TELEMETRY'}
                                    </button>
                                </div>

                                {/* TELEMETRY CHARTS GRID */}
                                {telemetryData.length > 0 && (
                                    <div className="space-y-4 pt-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
                                        <div className="flex items-center gap-4 mb-6">
                                            <h2 className="text-sm font-bold uppercase tracking-widest text-white">Data Trace</h2>
                                            <div className="h-px bg-white/10 flex-1"></div>
                                        </div>

                                        <TelemetrySingleChart title="Speed" data={telemetryData} dataKey="speed" stagedLaps={stagedLaps} />
                                        <TelemetrySingleChart title="Delta (vs Best)" data={telemetryData} dataKey="delta" stagedLaps={stagedLaps} />
                                        <TelemetrySingleChart title="Throttle" data={telemetryData} dataKey="throttle" stagedLaps={stagedLaps} />
                                        <TelemetrySingleChart title="Braking" data={telemetryData} dataKey="brake" stagedLaps={stagedLaps} />
                                        <TelemetrySingleChart title="RPM" data={telemetryData} dataKey="rpm" stagedLaps={stagedLaps} />
                                        <TelemetrySingleChart title="Gear" data={telemetryData} dataKey="gear" stagedLaps={stagedLaps} />
                                        <TelemetrySingleChart title="DRS" data={telemetryData} dataKey="drs" stagedLaps={stagedLaps} />

                                        <div className="pt-12 flex flex-col items-center">
                                            <button 
                                                onClick={fetchAIAnalysis}
                                                disabled={analyzing}
                                                className="w-full max-w-lg py-4 bg-f1-surface border border-f1-red text-white font-bold uppercase tracking-widest text-xs rounded hover:bg-f1-red transition-all duration-300 flex items-center justify-center gap-3 active:scale-95 shadow-[0_0_15px_rgba(255,30,0,0.2)]"
                                            >
                                                {analyzing ? (
                                                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                                                ) : (
                                                    <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-5 14H7v-2h7v2zm3-4H7v-2h10v2zm0-4H7V7h10v2z"/></svg>
                                                )}
                                                {analyzing ? 'GENERATING INSIGHTS...' : 'ASK AI ENGINEER'}
                                            </button>
                                            <div className="w-full mt-6">
                                                <AIAnalysis analysis={aiResult} isLoading={analyzing} />
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="h-[400px] border-2 border-dashed border-slate-800 rounded-lg flex items-center justify-center bg-transparent">
                                <span className="text-slate-600 font-mono text-xs uppercase tracking-[0.2em] font-medium">Select drivers to initialize lab</span>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </main>
    </div>
  );
};

import { CarData, Driver } from '../types';

export interface ProcessedCarData extends CarData {
    calculatedDistance: number;
    relativeTime: number; // Seconds from start of lap
}

const STEP_SIZE = 4; // Meters (High resolution for Delta)
const CORRELATION_SEARCH_RANGE = 50; // +/- steps for alignment

// Utility: Format seconds into m:ss.ms
export const formatLapTime = (seconds: number): string => {
    const m = (seconds / 60) | 0;
    const s = (seconds % 60).toFixed(3);
    return `${m}:${s.padStart(6, '0')}`;
};

/**
 * STEP 1: Enrich raw telemetry.
 * - Calculates cumulative distance (integral of speed).
 * - Calculates RELATIVE TIME (seconds) from lap start.
 */
const enrichAndFilter = (data: CarData[], lapStartDate: string, lapDuration: number) => {
    const len = data.length;
    if (len === 0) return null;

    // Convert lap start to epoch for reference
    const lapStartEpoch = new Date(lapStartDate).getTime();

    // Sort by date just in case (API usually handles this, but safety first)
    data.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const tempPoints: ProcessedCarData[] = new Array(len);
    let cumulativeDist = 0;

    for (let i = 0; i < len; i++) {
        const d = data[i];
        const currentEpoch = new Date(d.date).getTime();

        // Calculate Distance
        if (i > 0) {
            const prevEpoch = new Date(data[i-1].date).getTime();
            const timeDelta = (currentEpoch - prevEpoch) / 1000; // seconds
            const vCurrent = d.speed / 3.6; // km/h to m/s
            const vPrev = data[i-1].speed / 3.6;

            // Trapezoidal rule for distance integration
            const distDelta = ((vCurrent + vPrev) / 2) * timeDelta;

            // Filter noise/telemetry jumps
            if (distDelta > 0 && distDelta < 200) {
                cumulativeDist += distDelta;
            }
        }

        // Calculate Relative Time
        // We use the data's own timeline, normalized to 0 at the start trigger
        let relTime = (currentEpoch - lapStartEpoch) / 1000;

        tempPoints[i] = {
            ...d,
            calculatedDistance: cumulativeDist,
            relativeTime: relTime 
        };
    }

    // Align Start: Find the point closest to time=0 to zero-out distance
    // (OpenF1 data sometimes includes pre-lap data)
    let zeroDist = 0;
    const startPoint = tempPoints.find(p => p.relativeTime >= 0);
    if (startPoint) {
        zeroDist = startPoint.calculatedDistance;
    }

    const processed: ProcessedCarData[] = [];
    for(let i = 0; i < len; i++) {
        const p = tempPoints[i];
        // Filter to lap duration with a small buffer
        if (p.relativeTime >= -0.5 && p.relativeTime <= lapDuration + 1.0) {
            p.calculatedDistance = Math.max(0, p.calculatedDistance - zeroDist);
            processed.push(p);
        }
    }

    if (processed.length < 10) return null;
    const totalDist = processed[processed.length - 1].calculatedDistance;

    return { processed, totalDist };
};

/**
 * STEP 2: Normalize Distances (Rubber Banding).
 * Ensures all laps have the exact same total distance for comparison.
 */
const normalizeDistances = (inputs: { processed: ProcessedCarData[]; totalDist: number }[]): number => {
    let totalDistSum = 0;
    const len = inputs.length;
    for (let i = 0; i < len; i++) totalDistSum += inputs[i].totalDist;

    const standardDist = totalDistSum / len;

    for (let i = 0; i < len; i++) {
        const input = inputs[i];
        const factor = standardDist / input.totalDist;
        const pts = input.processed;
        const pLen = pts.length;
        for (let j = 0; j < pLen; j++) {
            pts[j].calculatedDistance = pts[j].calculatedDistance * factor;
        }
    }
    return standardDist;
};

/**
 * STEP 3: Resample Data (Linear Interpolation).
 * Projects all drivers onto a unified Distance Grid (e.g., 0m, 4m, 8m...).
 * Crucial for Delta: Interpolates TIME accurately at each grid step.
 */
const resampleData = (
    inputs: { traceId: string; processed: ProcessedCarData[] }[], 
    standardDist: number
) => {
    const steps = Math.floor(standardDist / STEP_SIZE);
    const combined: any[] = [];
    const numInputs = inputs.length;
    const cursors = new Int32Array(numInputs).fill(0);

    const keys = inputs.map(input => ({
        speed: `speed_${input.traceId}`,
        throttle: `throttle_${input.traceId}`,
        brake: `brake_${input.traceId}`,
        rpm: `rpm_${input.traceId}`,
        gear: `gear_${input.traceId}`,
        drs: `drs_${input.traceId}`,
        time: `time_${input.traceId}` // Dedicated field for calculation
    }));

    for (let i = 0; i <= steps; i++) {
        const currentDist = i * STEP_SIZE;
        const row: any = { distance: currentDist };
        let hasData = false;

        for (let idx = 0; idx < numInputs; idx++) {
            const { processed } = inputs[idx];
            const pLen = processed.length;
            let cursor = cursors[idx];

            // Fast-forward cursor to finding bounding points
            while (cursor < pLen - 2 && processed[cursor + 1].calculatedDistance <= currentDist) {
                cursor++;
            }
            cursors[idx] = cursor;

            const p1 = processed[cursor];
            const p2 = processed[cursor + 1];

            // Check if we are within valid bounds for interpolation
            if (p1 && p2 && p1.calculatedDistance <= currentDist && p2.calculatedDistance >= currentDist) {
                const distSpan = p2.calculatedDistance - p1.calculatedDistance;

                // Avoid division by zero
                if (distSpan > 0.0001) {
                    const ratio = (currentDist - p1.calculatedDistance) / distSpan;

                    // Linear Interpolation
                    row[keys[idx].speed] = Math.round(p1.speed + (p2.speed - p1.speed) * ratio);
                    row[keys[idx].throttle] = Math.round(p1.throttle + (p2.throttle - p1.throttle) * ratio);
                    row[keys[idx].brake] = Math.round(p1.brake + (p2.brake - p1.brake) * ratio);
                    row[keys[idx].rpm] = Math.round(p1.rpm + (p2.rpm - p1.rpm) * ratio);

                    // Nearest Neighbor for Discrete
                    row[keys[idx].gear] = ratio < 0.5 ? p1.n_gear : p2.n_gear;
                    row[keys[idx].drs] = (ratio < 0.5 ? p1.drs : p2.drs) > 9 ? 1 : 0; // Normalize DRS

                    // CRITICAL: Precise Time Interpolation for Delta
                    row[keys[idx].time] = p1.relativeTime + (p2.relativeTime - p1.relativeTime) * ratio;

                    hasData = true;
                }
            } else if (p1 && Math.abs(p1.calculatedDistance - currentDist) < STEP_SIZE) {
                // Edge case: End of lap
                row[keys[idx].speed] = p1.speed;
                row[keys[idx].time] = p1.relativeTime;
                hasData = true;
            }
        }

        if (hasData) combined.push(row);
    }
    return combined;
};

/**
 * STEP 4: Calculate Deltas (Before Alignment).
 * Math: Delta = DriverTime - RefTime.
 */
const calculateDeltasInPlace = (data: any[], traceIds: string[]) => {
    if (data.length === 0 || traceIds.length === 0) return;

    // 1. Identify Reference Lap (Fastest Lap = Lowest Time at Max Distance)
    // We look at the last valid row to compare total times
    let refId = traceIds[0];
    let minTime = Infinity;

    // Scan backward to find the last row where everyone has data (finish line)
    const lastRowIndex = data.length - 1;
    const lastRow = data[lastRowIndex];

    for (const id of traceIds) {
        const t = lastRow[`time_${id}`];
        if (typeof t === 'number' && t < minTime) {
            minTime = t;
            refId = id;
        }
    }

    // 2. Calculate Delta per row
    for (let i = 0; i < data.length; i++) {
        const row = data[i];
        const refTime = row[`time_${refId}`];

        for (const id of traceIds) {
            const driverTime = row[`time_${id}`];

            if (typeof refTime === 'number' && typeof driverTime === 'number') {
                // Delta Calculation
                // If DriverTime > RefTime, result is positive (Driver is Slower/Behind)
                // If DriverTime < RefTime, result is negative (Driver is Faster/Ahead)
                const delta = driverTime - refTime;
                row[`delta_${id}`] = delta;
            } else {
                row[`delta_${id}`] = null;
            }
        }
    }
};

/**
 * STEP 5: Visual Alignment (Cross-Correlation).
 * Shifts the data indices so corners align visually.
 * Important: We shift the 'delta' column too so it stays attached to the track position.
 */
const alignAndTrim = (combinedData: any[], traceIds: string[]) => {
    if (traceIds.length < 2 || combinedData.length === 0) return combinedData;

    const refTrace = traceIds[0];
    const refKey = `speed_${refTrace}`;
    const dataLen = combinedData.length;

    const refSpeed = new Float32Array(dataLen);
    for(let i=0; i<dataLen; i++) refSpeed[i] = Number(combinedData[i][refKey]) || 0;

    const alignedData = new Array(dataLen);
    // Deep clone to avoid mutation issues during shift
    for(let i=0; i<dataLen; i++) alignedData[i] = { ...combinedData[i] };

    for (let i = 1; i < traceIds.length; i++) {
        const traceId = traceIds[i];
        const targetKey = `speed_${traceId}`;

        const targetSpeed = new Float32Array(dataLen);
        for(let k=0; k<dataLen; k++) targetSpeed[k] = Number(combinedData[k][targetKey]) || 0;

        let minMSE = Infinity;
        let bestShift = 0;

        // Search for best alignment
        for (let shift = -CORRELATION_SEARCH_RANGE; shift <= CORRELATION_SEARCH_RANGE; shift++) {
            let sumSqDiff = 0;
            let count = 0;

            const start = shift < 0 ? -shift : 0;
            const end = shift > 0 ? dataLen - shift : dataLen;

            // Sample optimization: check every 2nd point for speed
            for (let j = start; j < end; j += 2) {
                const diff = refSpeed[j] - targetSpeed[j + shift];
                sumSqDiff += diff * diff;
                count++;
            }

            if (count > 0) {
                const mse = sumSqDiff / count;
                if (mse < minMSE) {
                    minMSE = mse;
                    bestShift = shift;
                }
            }
        }

        // Apply Shift
        if (bestShift !== 0) {
            const keysToShift = [
                `speed_${traceId}`, `throttle_${traceId}`, 
                `brake_${traceId}`, `rpm_${traceId}`, `gear_${traceId}`,
                `drs_${traceId}`, `time_${traceId}`, `delta_${traceId}`
            ];

            for (let j = 0; j < dataLen; j++) {
                const sourceIdx = j + bestShift;
                const row = alignedData[j];

                if (sourceIdx >= 0 && sourceIdx < dataLen) {
                    const srcRow = combinedData[sourceIdx];
                    for (const key of keysToShift) row[key] = srcRow[key];
                } else {
                    for (const key of keysToShift) row[key] = null;
                }
            }
        }
    }

    // Trim undefined edges
    let startIndex = 0;
    let endIndex = dataLen - 1;

    for (let i = 0; i < dataLen; i++) {
        const row = alignedData[i];
        if (traceIds.every(id => row[`speed_${id}`] != null)) {
            startIndex = i;
            break;
        }
    }
    for (let i = dataLen - 1; i >= 0; i--) {
         const row = alignedData[i];
         if (traceIds.every(id => row[`speed_${id}`] != null)) {
            endIndex = i;
            break;
        }
    }

    if (startIndex >= endIndex) return combinedData; // Fail safe

    const trimmed = alignedData.slice(startIndex, endIndex + 1);

    // Zero out distance after trim
    const offset = trimmed[0].distance;
    for(let i=0; i<trimmed.length; i++) trimmed[i].distance -= offset;

    return trimmed;
};

// --- MAIN PIPELINE ---
export const processTelemetryData = (
    inputs: { driver: Driver; data: CarData[]; lapStartDate: string; lapDuration: number; traceId: string }[]
) => {
    // 1. Enrich & Filter (Calc Relative Time)
    const enrichedInputs: { traceId: string; processed: ProcessedCarData[]; totalDist: number; driver: Driver }[] = [];

    for (const input of inputs) {
        const result = enrichAndFilter(input.data, input.lapStartDate, input.lapDuration);
        if (result) {
            enrichedInputs.push({ traceId: input.traceId, driver: input.driver, ...result });
        }
    }

    if (enrichedInputs.length === 0) return [];

    // 2. Normalize Distances (Rubber Banding)
    const standardDist = normalizeDistances(enrichedInputs);

    // 3. Resample (Interpolate Time on Grid)
    const combined = resampleData(enrichedInputs, standardDist);

    // 4. Calculate Deltas (Before shifting indices)
    calculateDeltasInPlace(combined, enrichedInputs.map(i => i.traceId));

    // 5. Align & Trim (Visual Correlation)
    const finalData = alignAndTrim(combined, enrichedInputs.map(i => i.traceId));

    return finalData;
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { getSessions, getDrivers, getLaps, getCarTelemetry, getLatestSession } from './services/openf1Service';
import { analyzeTelemetry } from './services/geminiService';
import { Session, Driver, Lap, AIAnalysisResult, StagedLap } from './types';
import SessionSelector from './components/SessionSelector';
import TelemetrySingleChart from './components/TelemetrySingleChart';
import AIAnalysis from './components/AIAnalysis';
import LapHistoryChart from './components/LapHistoryChart';
import DriverSelector from './components/DriverSelector';
import { processTelemetryData, formatLapTime } from './utils/telemetryUtils';
import { getTeamColors } from './utils/teamColors';
import { FALLBACK_COLOR } from './utils/chartUtils';

// --- CONSTANTS ---
const CURRENT_YEAR = new Date().getFullYear();
const START_YEAR = 2023;
const AVAILABLE_YEARS = Array.from({ length: CURRENT_YEAR - START_YEAR + 1 }, (_, i) => CURRENT_YEAR - i);
const MAX_LAPS = 8;

export const App: React.FC = () => {
  // --- STATE ---
  const [selectedYear, setSelectedYear] = useState<number>(CURRENT_YEAR);
  const [sessions, setSessions] = useState<Session[]>([]);
  const [selectedSession, setSelectedSession] = useState<Session | null>(null);

  const [allDrivers, setAllDrivers] = useState<Driver[]>([]);
  const [selectedDrivers, setSelectedDrivers] = useState<Driver[]>([]);

  const pendingRandomCountRef = useRef<number | null>(null);
  const [isRandomizing, setIsRandomizing] = useState(false);

  // Data Containers
  const [lapsData, setLapsData] = useState<Map<number, Lap[]>>(new Map());
  const [stagedLaps, setStagedLaps] = useState<StagedLap[]>([]);
  const [telemetryData, setTelemetryData] = useState<any[]>([]);

  // Loading States
  const [loadingLaps, setLoadingLaps] = useState(false);
  const [loadingTelemetry, setLoadingTelemetry] = useState(false);
  const [loadingSessions, setLoadingSessions] = useState(false);

  const [aiResult, setAiResult] = useState<AIAnalysisResult | null>(null);
  const [analyzing, setAnalyzing] = useState(false);

  // --- INITIALIZATION ---
  useEffect(() => {
    let mounted = true;
    const init = async () => {
        setLoadingSessions(true);
        try {
            const latest = await getLatestSession();
            if(!mounted) return;

            if(latest) {
                setSelectedYear(latest.year);
                const allSessions = await getSessions(latest.year);
                if(mounted) {
                    setSessions(allSessions);
                    setSelectedSession(latest);
                }
            } else {
                const allSessions = await getSessions(selectedYear);
                if(mounted) setSessions(allSessions);
            }
        } catch (e) {
            console.error("Init Error", e);
        } finally {
            if(mounted) setLoadingSessions(false);
        }
    };
    init();
    return () => { mounted = false; };
  }, []);

  // --- DRIVER LOADING ---
  useEffect(() => {
    if (!selectedSession) return;
    let mounted = true;
    const loadDrivers = async () => {
        try {
            const d = await getDrivers(selectedSession.session_key);
            if (mounted) {
                const unique = d.filter((v, i, a) => a.findIndex(t => (t.driver_number === v.driver_number)) === i);
                setAllDrivers(unique);

                if (pendingRandomCountRef.current !== null) {
                    const count = pendingRandomCountRef.current;
                    const shuffled = [...unique].sort(() => 0.5 - Math.random());
                    setSelectedDrivers(shuffled.slice(0, count));
                    pendingRandomCountRef.current = null;
                } else {
                    setSelectedDrivers([]);
                }
                setLapsData(new Map());
                setStagedLaps([]);
                setTelemetryData([]);
            }
        } catch (e) { console.error(e); }
    };
    loadDrivers();
    return () => { mounted = false; };
  }, [selectedSession]);

  // --- HANDLERS ---
  const handleYearChange = async (year: number) => {
      if(year === selectedYear) return;
      setSelectedYear(year);
      setLoadingSessions(true);
      setSelectedSession(null);
      setSessions([]);

      try {
          const newSessions = await getSessions(year);
          setSessions(newSessions);
          if (newSessions.length > 0) setSelectedSession(newSessions[0]);
      } catch (e) { console.error(e); } 
      finally { setLoadingSessions(false); }
  };

  const handleRefreshSessions = async () => {
      setLoadingSessions(true);
      try {
          const freshSessions = await getSessions(selectedYear);
          setSessions(freshSessions);
          if (selectedSession) {
              const stillExists = freshSessions.find(s => s.session_key === selectedSession.session_key);
              if (stillExists) setSelectedSession(stillExists);
          } else if (freshSessions.length > 0) {
               setSelectedSession(freshSessions[0]);
          }
      } catch (e) { console.error(e); } 
      finally { setLoadingSessions(false); }
  };

  const handleToggleDriver = (driver: Driver) => {
      const exists = selectedDrivers.find(d => d.driver_number === driver.driver_number);
      if (exists) {
          setSelectedDrivers(prev => prev.filter(d => d.driver_number !== driver.driver_number));
          setLapsData(prev => {
              const next = new Map(prev);
              next.delete(driver.driver_number);
              return next;
          });
          setStagedLaps(prev => prev.filter(sl => sl.driver.driver_number !== driver.driver_number));
      } else {
          if (selectedDrivers.length < 6) setSelectedDrivers(prev => [...prev, driver]);
      }
  };

  const loadLapHistory = useCallback(async () => {
      if (!selectedSession || selectedDrivers.length === 0) return;
      setLoadingLaps(true);
      const newLapsMap = new Map<number, Lap[]>();
      try {
          await Promise.all(selectedDrivers.map(async (d) => {
              const laps = await getLaps(selectedSession.session_key, d.driver_number);
              const validLaps = laps.filter(l => l.lap_duration > 0);
              newLapsMap.set(d.driver_number, validLaps);
          }));
          setLapsData(newLapsMap);
          setStagedLaps([]); 
      } catch (e) { console.error(e); } 
      finally { setLoadingLaps(false); }
  }, [selectedSession, selectedDrivers]);

  useEffect(() => {
      if (isRandomizing && selectedDrivers.length > 0) {
          loadLapHistory();
          setIsRandomizing(false);
      }
  }, [selectedDrivers, isRandomizing, loadLapHistory]);

  const syncTelemetry = async () => {
      if (!selectedSession || stagedLaps.length === 0) return;
      setLoadingTelemetry(true);
      setAiResult(null);

      try {
          const inputs = await Promise.all(stagedLaps.map(async (sl) => {
              const { driver, lap } = sl;
              const buffer = 1.5; 
              const data = await getCarTelemetry(
                  selectedSession.session_key, 
                  driver.driver_number, 
                  new Date(new Date(lap.date_start).getTime() - 1500).toISOString(), 
                  new Date(new Date(lap.date_start).getTime() + (lap.lap_duration + buffer) * 1000).toISOString()
              );
              const traceId = `${driver.name_acronym}_L${lap.lap_number}`;
              return { driver, data, lapStartDate: lap.date_start, lapDuration: lap.lap_duration, traceId };
          }));

          const validInputs = inputs.filter(i => i.data && i.data.length > 0);
          if (validInputs.length > 0) {
              const processed = processTelemetryData(validInputs);
              setTelemetryData(processed);
          }
      } catch(e) { console.error(e); } 
      finally { setLoadingTelemetry(false); }
  };

  const handleRandomize = useCallback(async () => {
      setLoadingSessions(true);
      setSelectedDrivers([]); 
      setLapsData(new Map());
      setStagedLaps([]);
      setTelemetryData([]);
      setIsRandomizing(true);
      try {
          const randomYear = AVAILABLE_YEARS[Math.floor(Math.random() * AVAILABLE_YEARS.length)];
          const allSessions = await getSessions(randomYear);
          const qualifyingSessions = allSessions.filter(s => s.session_name === 'Qualifying');

          if (qualifyingSessions.length === 0) {
             setLoadingSessions(false); setIsRandomizing(false); return;
          }

          const randomSession = qualifyingSessions[Math.floor(Math.random() * qualifyingSessions.length)];
          const count = Math.floor(Math.random() * 3) + 2; 

          pendingRandomCountRef.current = count;
          setSelectedYear(randomYear);
          setSessions(allSessions);
          setSelectedSession(randomSession);

      } catch (e) {
          console.error(e); setIsRandomizing(false);
      } finally { setLoadingSessions(false); }
  }, []);

  const stagePBLaps = () => {
      const newStaged = [...stagedLaps];
      selectedDrivers.forEach(d => {
          if (newStaged.length >= MAX_LAPS) return;
          const laps = lapsData.get(d.driver_number) || [];
          if (laps.length > 0) {
              const pb = [...laps].sort((a,b) => a.lap_duration - b.lap_duration)[0];
              const id = `${d.driver_number}_${pb.lap_number}`;
              if (!newStaged.find(s => s.id === id)) {
                   newStaged.push({ id, driver: d, lap: pb, color: '' });
              }
          }
      });
      setStagedLaps(newStaged);
  };

  const handleToggleLap = useCallback((driver: Driver, lap: Lap) => {
      const id = `${driver.driver_number}_${lap.lap_number}`;

      setStagedLaps(prev => {
          const existsIdx = prev.findIndex(s => s.id === id);

          if (existsIdx >= 0) {
              const newStaged = [...prev];
              newStaged.splice(existsIdx, 1);
              return newStaged;
          } else {
              if (prev.length < MAX_LAPS) {
                 setTimeout(() => {
                    const el = document.getElementById(`staged-lap-${id}`);
                    if (el && typeof el.scrollIntoView === 'function') {
                        el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                    }
                 }, 100);

                 return [...prev, { id, driver, lap, color: '' }];
              }
              return prev;
          }
      });
  }, []);

  const fetchAIAnalysis = async () => {
    if (stagedLaps.length === 0 || telemetryData.length === 0) return;
    setAnalyzing(true);
    try {
        const aiSampleRate = Math.max(1, Math.floor(telemetryData.length / 50));
        const colors = getTeamColors(stagedLaps.map(s => s.driver));

        const inputs = stagedLaps.map((sl, index) => {
            const { driver, lap } = sl;
            const traceId = `${driver.name_acronym}_L${lap.lap_number}`;
            const formattedT = telemetryData
                .filter((_, i) => i % aiSampleRate === 0)
                .map(row => ({
                    date: '', distance: row.distance,
                    speed: row[`speed_${traceId}`] || 0,
                    throttle: row[`throttle_${traceId}`] || 0,
                    brake: row[`brake_${traceId}`] || 0,
                    rpm: row[`rpm_${traceId}`] || 0,
                    gear: row[`gear_${traceId}`] || 0,
                    drs: row[`drs_${traceId}`] || 0,
                    delta: row[`delta_${traceId}`] || 0,
                    driver: driver.name_acronym, color: colors[index]
                }));
            return { driver, lap, telemetry: formattedT, label: `${driver.name_acronym} (L${lap.lap_number})` };
        });

        const res = await analyzeTelemetry(inputs);
        setAiResult(res);
    } catch (error) { console.error(error); } 
    finally { setAnalyzing(false); }
  };

  const isHistorySynced = useMemo(() => {
      if (loadingLaps || selectedDrivers.length === 0) return false;
      return selectedDrivers.every(d => lapsData.has(d.driver_number) && (lapsData.get(d.driver_number)?.length || 0) > 0);
  }, [selectedDrivers, lapsData, loadingLaps]);

  const allTelemetryColors = useMemo(() => 
    getTeamColors(stagedLaps.map(s => s.driver)), 
  [stagedLaps]);

  return (
    <div className="min-h-screen w-full bg-[#09090b] text-white font-sans flex flex-col overflow-x-hidden selection:bg-f1-red/30">
        <header className="sticky top-0 z-50 w-full bg-[#09090b] border-b border-white/5 px-6 py-4 flex items-center justify-between shadow-md">
            <div className="flex items-center gap-3">
                <div className="w-8 h-8 bg-f1-red rounded-sm flex items-center justify-center shadow-[0_0_15px_rgba(255,30,0,0.5)]">
                    <span className="font-mono font-bold text-white text-lg">S</span>
                </div>
                <div className="flex flex-col leading-none">
                     <h1 className="font-sans text-xl font-bold tracking-tight text-white uppercase">StintLogic<span className="text-f1-red">.com</span></h1>
                     <span className="text-[9px] text-f1-muted uppercase tracking-[0.25em]">Telemetry Lab</span>
                </div>
            </div>
        </header>

        <main className="flex-1 w-full p-6 space-y-6 bg-[#09090b] bg-[radial-gradient(#ffffff08_1px,#09090b_1px)] [background-size:20px_20px]">
            <div className="container mx-auto">
