    if (inputs.length === 0) return [];

    // 1. Define Shared Grid Extents
    // We stop at the shortest lap distance to avoid extrapolating into the unknown
    const minTotalDist = Math.min(...inputs.map(i => i.totalDist));
    const steps = Math.floor(minTotalDist / STEP_SIZE);

    // 2. Prepare Data Structures
    // We pre-calculate interpolated values for every trace
    const tracesData = inputs.map(input => {
        const p = input.processed;
        const pLen = p.length;

        // Output arrays aligned to the grid
        const times = new Float32Array(steps + 1);
        const speeds = new Float32Array(steps + 1);
        const rpms = new Float32Array(steps + 1);
        const throttles = new Float32Array(steps + 1);
        const brakes = new Float32Array(steps + 1);
        const gears = new Int32Array(steps + 1);
        const drs = new Int32Array(steps + 1);

        let cursor = 0;

        for (let i = 0; i <= steps; i++) {
            const targetDist = i * STEP_SIZE;

            // Advance cursor to finding bounding points [p1, p2]
            while (cursor < pLen - 2 && p[cursor + 1].calculatedDistance <= targetDist) {
                cursor++;
            }

            const p1 = p[cursor];
            const p2 = p[cursor + 1];

            if (p1 && p2) {
                // Interpolate
                times[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.relativeTime, p2.relativeTime);
                speeds[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.speed, p2.speed);
                rpms[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.rpm, p2.rpm);
                throttles[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.throttle, p2.throttle);
                brakes[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.brake, p2.brake);

                // Nearest Neighbor for discrete
                const ratio = (targetDist - p1.calculatedDistance) / (p2.calculatedDistance - p1.calculatedDistance);
                gears[i] = ratio < 0.5 ? p1.n_gear : p2.n_gear;
                drs[i] = (ratio < 0.5 ? p1.drs : p2.drs) > 8 ? 1 : 0;
            } else {
                // End of data fallback
                times[i] = p1.relativeTime;
                speeds[i] = p1.speed;
            }
        }

        return {
            traceId: input.traceId,
            times, speeds, rpms, throttles, brakes, gears, drs
        };
    });

    // 3. Identify Reference Lap (Fastest Total Time)
    // We look at the last interpolated time point
    let refIndex = 0;
    let minTime = Infinity;

    tracesData.forEach((t, idx) => {
        const totalTime = t.times[steps]; // Last point time
        if (totalTime < minTime) {
            minTime = totalTime;
            refIndex = idx;
        }
    });

    const refTrace = tracesData[refIndex];

    // 4. Construct Final Rows
    const combinedData = [];

    for (let i = 0; i <= steps; i++) {
        const dist = i * STEP_SIZE;
        const row: any = { distance: dist };

        const refTimeAtDist = refTrace.times[i];

        tracesData.forEach(t => {
            const id = t.traceId;
            // Add telemetry values
            row[`speed_${id}`] = Math.round(t.speeds[i]);
            row[`rpm_${id}`] = Math.round(t.rpms[i]);
            row[`throttle_${id}`] = Math.round(t.throttles[i]);
            row[`brake_${id}`] = Math.round(t.brakes[i]);
            row[`gear_${id}`] = t.gears[i];
            row[`drs_${id}`] = t.drs[i];

            // CALCULATE DELTA
            // Standard Formula: DriverTime - RefTime
            // If Driver is behind, DriverTime is larger -> Delta is Positive
            const compTimeAtDist = t.times[i];
            row[`delta_${id}`] = compTimeAtDist - refTimeAtDist;

            // Store time for debugging if needed
            row[`time_${id}`] = compTimeAtDist;
        });

        combinedData.push(row);
    }

    return combinedData;
};

// --- MAIN PIPELINE ---
export const processTelemetryData = (
    inputs: { driver: Driver; data: CarData[]; lapStartDate: string; lapDuration: number; traceId: string }[]
) => {
    // 1. Enrich (Calc Dist, Zero Time)
    const enrichedInputs = [];
    for (const input of inputs) {
        const result = enrichAndFilter(input.data, input.lapStartDate, input.lapDuration);
        if (result) {
            enrichedInputs.push({ 
                traceId: input.traceId, 
                processed: result.processed, 
                totalDist: result.totalDist 
            });
        }
    }

    if (enrichedInputs.length === 0) return [];

    // 2. Build Grid & Calc Delta
    // This function handles the resampling and delta logic internally
    const finalData = buildUnifiedGrid(enrichedInputs);

    return finalData;
};

import { CarData, Driver } from '../types';

export interface ProcessedCarData extends CarData {
    calculatedDistance: number;
    relativeTime: number; // Seconds from start of lap (strictly 0-based)
}

const STEP_SIZE = 5; // Meters (Standard Grid Resolution)
const MIN_SPEED_KPH = 10; // Clamp speed to avoid division by zero or massive spikes

// Utility: Format seconds into m:ss.ms
export const formatLapTime = (seconds: number): string => {
    const m = (seconds / 60) | 0;
    const s = (seconds % 60).toFixed(3);
    return `${m}:${s.padStart(6, '0')}`;
};

/**
 * STEP 1: Enrich raw telemetry.
 * Calculates Distance (Integral of Speed) and Relative Time.
 * Forces the lap to start at (0m, 0s).
 */
const enrichAndFilter = (data: CarData[], lapStartDate: string, lapDuration: number) => {
    const len = data.length;
    if (len === 0) return null;

    // Ensure chronological order
    data.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const tempPoints: ProcessedCarData[] = new Array(len);
    let cumulativeDist = 0;

    // 1. Calculate Distances based on Speed Integral
    for (let i = 0; i < len; i++) {
        const d = data[i];
        if (i > 0) {
            const prev = data[i-1];
            const timeDelta = (new Date(d.date).getTime() - new Date(prev.date).getTime()) / 1000;
            const vCurrent = d.speed / 3.6; // km/h to m/s
            const vPrev = prev.speed / 3.6;

            // Trapezoidal integration
            const distDelta = ((vCurrent + vPrev) / 2) * timeDelta;

            // Filter physics anomalies (teleportation glitches)
            if (distDelta >= 0 && distDelta < 150) { 
                cumulativeDist += distDelta;
            }
        }
        tempPoints[i] = { ...d, calculatedDistance: cumulativeDist, relativeTime: 0 };
    }

    // 2. Filter to Lap Window & Strict Zeroing
    const lapStartEpoch = new Date(lapStartDate).getTime();

    // Select points that cover the lap (with small buffer)
    const relevantPoints = tempPoints.filter(p => {
        const t = (new Date(p.date).getTime() - lapStartEpoch) / 1000;
        return t >= -1.0 && t <= lapDuration + 1.0;
    });

    if (relevantPoints.length < 10) return null;

    // Set Origin: First point is (0m, 0s)
    const originDist = relevantPoints[0].calculatedDistance;
    const originTime = new Date(relevantPoints[0].date).getTime();

    const processed: ProcessedCarData[] = [];
    for (let i = 0; i < relevantPoints.length; i++) {
        const p = relevantPoints[i];
        p.relativeTime = (new Date(p.date).getTime() - originTime) / 1000;
        p.calculatedDistance = Math.max(0, p.calculatedDistance - originDist);
        processed.push(p);
    }

    const totalDist = processed[processed.length - 1].calculatedDistance;

    return { processed, totalDist };
};

/**
 * HELPER: Linear Interpolation
 */
const lerp = (x: number, x0: number, x1: number, y0: number, y1: number) => {
    if (Math.abs(x1 - x0) < 0.00001) return y0;
    return y0 + (x - x0) * (y1 - y0) / (x1 - x0);
};

/**
 * STEP 2, 3 & 4: Velocity Integration Delta
 * 
 * Algorithm:
 * 1. Resample all data (Speed, Time, RPM) onto a unified Distance Grid.
 * 2. Identify Reference Driver.
 * 3. Calculate Delta by Integrating the difference in "Pace" (Time per Meter).
 *    Delta_Seg = (Step / V_Comp) - (Step / V_Ref)
 * 4. Apply Bias Correction (Drift Adjustment) to match actual Lap Time difference.
 */
const buildUnifiedGrid = (
    inputs: { traceId: string; processed: ProcessedCarData[]; totalDist: number }[]
) => {
    if (inputs.length === 0) return [];

    // 1. Define Shared Grid Extents
    const minTotalDist = Math.min(...inputs.map(i => i.totalDist));
    const steps = Math.floor(minTotalDist / STEP_SIZE);

    // 2. Pre-Calculate Interpolated Profiles for all traces
    const tracesData = inputs.map(input => {
        const p = input.processed;
        const pLen = p.length;

        // Output arrays aligned to the grid
        const speeds = new Float32Array(steps + 1);
        const times = new Float32Array(steps + 1); // Needed for Drift Correction check
        const rpms = new Float32Array(steps + 1);
        const throttles = new Float32Array(steps + 1);
        const brakes = new Float32Array(steps + 1);
        const gears = new Int32Array(steps + 1);
        const drs = new Int32Array(steps + 1);

        let cursor = 0;

        for (let i = 0; i <= steps; i++) {
            const targetDist = i * STEP_SIZE;

            while (cursor < pLen - 2 && p[cursor + 1].calculatedDistance <= targetDist) {
                cursor++;
            }

            const p1 = p[cursor];
            const p2 = p[cursor + 1];

            if (p1 && p2) {
                // Linear Interpolation
                times[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.relativeTime, p2.relativeTime);
                // Clamp speed for physics calculations later
                const rawSpeed = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.speed, p2.speed);
                speeds[i] = Math.max(rawSpeed, MIN_SPEED_KPH); 

                rpms[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.rpm, p2.rpm);
                throttles[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.throttle, p2.throttle);
                brakes[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.brake, p2.brake);

                // Nearest Neighbor
                const ratio = (targetDist - p1.calculatedDistance) / (p2.calculatedDistance - p1.calculatedDistance);
                gears[i] = ratio < 0.5 ? p1.n_gear : p2.n_gear;
                drs[i] = (ratio < 0.5 ? p1.drs : p2.drs) > 8 ? 1 : 0;
            } else {
                times[i] = p1.relativeTime;
                speeds[i] = Math.max(p1.speed, MIN_SPEED_KPH);
            }
        }

        return {
            traceId: input.traceId,
            times, speeds, rpms, throttles, brakes, gears, drs
        };
    });

    // 3. Identify Reference Lap (Fastest Total Time)
    // We use the interpolated time at the final grid point to be consistent
    let refIndex = 0;
    let minTime = Infinity;

    tracesData.forEach((t, idx) => {
        const totalTime = t.times[steps]; 
        if (totalTime < minTime) {
            minTime = totalTime;
            refIndex = idx;
        }
    });

    const refTrace = tracesData[refIndex];
    const refSpeeds = refTrace.speeds;

    // 4. Calculate Delta via Integration & Assemble Final Data
    // We create a temporary array to store the integrated deltas before mixing them into the final object
    const calculatedDeltas = tracesData.map(trace => {
        if (trace.traceId === refTrace.traceId) return new Float32Array(steps + 1).fill(0);

        const integratedDelta = new Float32Array(steps + 1);
        let currentDelta = 0;

        for (let i = 1; i <= steps; i++) {
            // Speed in m/s
            const vRef = refSpeeds[i] / 3.6;
            const vComp = trace.speeds[i] / 3.6;

            // Time to travel this segment (STEP_SIZE)
            // t = d / v
            const tRefSeg = STEP_SIZE / vRef;
            const tCompSeg = STEP_SIZE / vComp;

            // Delta gained/lost in this specific segment
            // If Comp is slower (vComp < vRef), tComp is larger -> Delta increases
            const segmentDelta = tCompSeg - tRefSeg;

            currentDelta += segmentDelta;
            integratedDelta[i] = currentDelta;
        }

        // BIAS CORRECTION (DRIFT ADJUSTMENT)
        // Compare the integrated mathematical delta vs the actual stopwatch difference
        const actualTimeDiff = trace.times[steps] - refTrace.times[steps];
        const integratedTimeDiff = integratedDelta[steps];
        const error = actualTimeDiff - integratedTimeDiff;

        // Distribute error linearly across the lap (Tilt the graph)
        const correctedDelta = new Float32Array(steps + 1);
        const totalDist = steps * STEP_SIZE;

        for(let i = 0; i <= steps; i++) {
            const dist = i * STEP_SIZE;
            const correction = (dist / totalDist) * error;
            correctedDelta[i] = integratedDelta[i] + correction;
        }

        return correctedDelta;
    });

    // 5. Construct Final Output Array
    const combinedData = [];

    for (let i = 0; i <= steps; i++) {
        const dist = i * STEP_SIZE;
        const row: any = { distance: dist };

        tracesData.forEach((t, idx) => {
            const id = t.traceId;

            row[`speed_${id}`] = Math.round(t.speeds[i]);
            row[`rpm_${id}`] = Math.round(t.rpms[i]);
            row[`throttle_${id}`] = Math.round(t.throttles[i]);
            row[`brake_${id}`] = Math.round(t.brakes[i]);
            row[`gear_${id}`] = t.gears[i];
            row[`drs_${id}`] = t.drs[i];

            // Assign the integrated & corrected delta
            row[`delta_${id}`] = calculatedDeltas[idx][i];

            // Keep raw time for debugging if needed
            row[`time_${id}`] = t.times[i];
        });

        combinedData.push(row);
    }

    return combinedData;
};

// --- MAIN PIPELINE ---
export const processTelemetryData = (
    inputs: { driver: Driver; data: CarData[]; lapStartDate: string; lapDuration: number; traceId: string }[]
) => {
    // 1. Enrich (Calc Dist, Zero Time)
    const enrichedInputs = [];
    for (const input of inputs) {
        const result = enrichAndFilter(input.data, input.lapStartDate, input.lapDuration);
        if (result) {
            enrichedInputs.push({ 
                traceId: input.traceId, 
                processed: result.processed, 
                totalDist: result.totalDist 
            });
        }
    }

    if (enrichedInputs.length === 0) return [];

    // 2. Build Grid & Calc Integral Delta
    const finalData = buildUnifiedGrid(enrichedInputs);

    return finalData;
};

