import { CarData, Driver } from '../types';

export interface ProcessedCarData extends CarData {
    calculatedDistance: number;
    relativeTime: number; // Seconds from start of lap (strictly 0-based)
}

const STEP_SIZE = 5; // Meters (Reference Grid Resolution)
const SMA_WINDOW = 15; // Smoothing Window Size (number of samples)

// Utility: Format seconds into m:ss.ms
export const formatLapTime = (seconds: number): string => {
    const m = (seconds / 60) | 0;
    const s = (seconds % 60).toFixed(3);
    return `${m}:${s.padStart(6, '0')}`;
};

/**
 * HELPER: Simple Moving Average (SMA)
 * Smooths the delta curve to remove GPS micro-jitter.
 */
const applySmoothing = (values: number[], windowSize: number): number[] => {
    if (values.length < windowSize) return values;

    const smoothed = new Float32Array(values.length);
    const halfWindow = Math.floor(windowSize / 2);

    for (let i = 0; i < values.length; i++) {
        let sum = 0;
        let count = 0;

        // Calculate average for window around i
        const start = Math.max(0, i - halfWindow);
        const end = Math.min(values.length - 1, i + halfWindow);

        for (let j = start; j <= end; j++) {
            sum += values[j];
            count++;
        }

        smoothed[i] = sum / count;
    }

    // Convert back to number[] (or keep as Float32Array, but chart libs prefer standard arrays)
    return Array.from(smoothed);
};

/**
 * HELPER: Linear Interpolation
 */
const lerp = (x: number, x0: number, x1: number, y0: number, y1: number) => {
    if (Math.abs(x1 - x0) < 0.00001) return y0;
    return y0 + (x - x0) * (y1 - y0) / (x1 - x0);
};

/**
 * STEP 1: Enrich raw telemetry.
 * Calculates Distance (Integral of Speed) and Relative Time.
 */
const enrichAndFilter = (data: CarData[], lapStartDate: string, lapDuration: number) => {
    const len = data.length;
    if (len === 0) return null;

    data.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const tempPoints: ProcessedCarData[] = new Array(len);
    let cumulativeDist = 0;

    // 1. Calculate Distances based on Speed Integral
    for (let i = 0; i < len; i++) {
        const d = data[i];
        if (i > 0) {
            const prev = data[i-1];
            const timeDelta = (new Date(d.date).getTime() - new Date(prev.date).getTime()) / 1000;
            const vCurrent = d.speed / 3.6; // km/h to m/s
            const vPrev = prev.speed / 3.6;

            // Trapezoidal integration
            const distDelta = ((vCurrent + vPrev) / 2) * timeDelta;

            // Basic physics filter
            if (distDelta >= 0 && distDelta < 150) { 
                cumulativeDist += distDelta;
            }
        }
        tempPoints[i] = { ...d, calculatedDistance: cumulativeDist, relativeTime: 0 };
    }

    // 2. Filter to Lap Window & Strict Zeroing
    const lapStartEpoch = new Date(lapStartDate).getTime();
    const relevantPoints = tempPoints.filter(p => {
        const t = (new Date(p.date).getTime() - lapStartEpoch) / 1000;
        return t >= -1.0 && t <= lapDuration + 1.0;
    });

    if (relevantPoints.length < 10) return null;

    const originDist = relevantPoints[0].calculatedDistance;
    const originTime = new Date(relevantPoints[0].date).getTime();

    const processed: ProcessedCarData[] = [];
    for (let i = 0; i < relevantPoints.length; i++) {
        const p = relevantPoints[i];
        p.relativeTime = (new Date(p.date).getTime() - originTime) / 1000;
        p.calculatedDistance = Math.max(0, p.calculatedDistance - originDist);
        processed.push(p);
    }

    const totalDist = processed[processed.length - 1].calculatedDistance;

    return { processed, totalDist };
};

/**
 * STEP 2: NORMALIZED DISTANCE INTERPOLATION
 * 
 * Algorithm:
 * 1. Identify Reference Driver (Fastest Lap).
 * 2. Create X-Axis based on Reference Driver's Meters (0, 5, 10...).
 * 3. For each point on X-Axis:
 *    a. Calculate Percentage of Lap Completed (Pct = Current_Ref_Meters / Total_Ref_Meters).
 *    b. Get Reference Telemetry at Current_Ref_Meters.
 *    c. Find equivalent point for Comparison Driver at `Pct * Total_Comp_Meters`.
 *    d. Delta = Comp_Time_At_Pct - Ref_Time_At_Pct.
 * 4. Apply Smoothing to Delta.
 */
const buildNormalizedGrid = (
    inputs: { traceId: string; processed: ProcessedCarData[]; totalDist: number }[]
) => {
    if (inputs.length === 0) return [];

    // 1. Identify Reference Lap (Fastest Total Time)
    // We determine this by checking the last relativeTime of each processed array
    let refIndex = 0;
    let minLapTime = Infinity;

    inputs.forEach((input, idx) => {
        const lastPt = input.processed[input.processed.length - 1];
        if (lastPt.relativeTime < minLapTime) {
            minLapTime = lastPt.relativeTime;
            refIndex = idx;
        }
    });

    const refInput = inputs[refIndex];
    const refTotalDist = refInput.totalDist;

    // Define Grid based on Reference Distance
    const steps = Math.floor(refTotalDist / STEP_SIZE);

    // Prepare Data Containers
    // We calculate raw data first, then apply smoothing, then combine
    const traceResults = inputs.map(input => {
        const isRef = input.traceId === refInput.traceId;
        const totalDist = input.totalDist;
        const p = input.processed;
        const pLen = p.length;

        const res = {
            traceId: input.traceId,
            times: new Float32Array(steps + 1),
            speeds: new Float32Array(steps + 1),
            rpms: new Float32Array(steps + 1),
            throttles: new Float32Array(steps + 1),
            brakes: new Float32Array(steps + 1),
            gears: new Int32Array(steps + 1),
            drs: new Int32Array(steps + 1),
            deltas: new Float32Array(steps + 1) // Raw deltas
        };

        let cursor = 0;

        for (let i = 0; i <= steps; i++) {
            // THE CORE LOGIC:
            // 1. Calculate percentage of lap for this grid point based on Reference
            const currentRefDist = i * STEP_SIZE;
            const pct = currentRefDist / refTotalDist;

            // 2. Map this percentage to the SPECIFIC driver's distance
            // If this is the reference, it's just currentRefDist.
            // If this is comparison, it handles the trajectory difference.
            const targetDist = pct * totalDist;

            // 3. Interpolate this driver's data at targetDist
            while (cursor < pLen - 2 && p[cursor + 1].calculatedDistance <= targetDist) {
                cursor++;
            }

            const p1 = p[cursor];
            const p2 = p[cursor + 1];

            if (p1 && p2) {
                res.times[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.relativeTime, p2.relativeTime);
                res.speeds[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.speed, p2.speed);
                res.rpms[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.rpm, p2.rpm);
                res.throttles[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.throttle, p2.throttle);
                res.brakes[i] = lerp(targetDist, p1.calculatedDistance, p2.calculatedDistance, p1.brake, p2.brake);

                const ratio = (targetDist - p1.calculatedDistance) / (p2.calculatedDistance - p1.calculatedDistance);
                res.gears[i] = ratio < 0.5 ? p1.n_gear : p2.n_gear;
                res.drs[i] = (ratio < 0.5 ? p1.drs : p2.drs) > 8 ? 1 : 0;
            } else {
                res.times[i] = p1.relativeTime;
                res.speeds[i] = p1.speed;
            }
        }
        return res;
    });

    // 4. Calculate Deltas and Apply Smoothing
    // We already interpolated times based on shared Pct. Now Delta = Time_Comp - Time_Ref.
    const refTraceResult = traceResults.find(t => t.traceId === refInput.traceId)!;

    const smoothedTraceResults = traceResults.map(t => {
        if (t.traceId === refInput.traceId) {
            return { ...t, smoothedDeltas: new Float32Array(steps + 1).fill(0) };
        }

        const rawDeltas = [];
        for (let i = 0; i <= steps; i++) {
            const compTime = t.times[i];
            const refTime = refTraceResult.times[i];
            rawDeltas.push(compTime - refTime);
        }

        const smoothed = applySmoothing(rawDeltas, SMA_WINDOW);
        return { ...t, smoothedDeltas: smoothed };
    });

    // 5. Construct Final Combined Object
    const combinedData = [];

    for (let i = 0; i <= steps; i++) {
        const dist = i * STEP_SIZE;
        const row: any = { distance: dist };

        smoothedTraceResults.forEach(t => {
            const id = t.traceId;
            row[`speed_${id}`] = Math.round(t.speeds[i]);
            row[`rpm_${id}`] = Math.round(t.rpms[i]);
            row[`throttle_${id}`] = Math.round(t.throttles[i]);
            row[`brake_${id}`] = Math.round(t.brakes[i]);
            row[`gear_${id}`] = t.gears[i];
            row[`drs_${id}`] = t.drs[i];

            // Use the Smoothed Delta
            row[`delta_${id}`] = t.smoothedDeltas[i];

            // Debug time
            row[`time_${id}`] = t.times[i];
        });

        combinedData.push(row);
    }

    return combinedData;
};

// --- MAIN PIPELINE ---
export const processTelemetryData = (
    inputs: { driver: Driver; data: CarData[]; lapStartDate: string; lapDuration: number; traceId: string }[]
) => {
    // 1. Enrich
    const enrichedInputs = [];
    for (const input of inputs) {
        const result = enrichAndFilter(input.data, input.lapStartDate, input.lapDuration);
        if (result) {
            enrichedInputs.push({ 
                traceId: input.traceId, 
                processed: result.processed, 
                totalDist: result.totalDist 
            });
        }
    }

    if (enrichedInputs.length === 0) return [];

    // 2. Build Grid via Normalized Distance
    const finalData = buildNormalizedGrid(enrichedInputs);

    return finalData;
};

