                // True Gap = CompTotalTime - RefTotalTime
                // Graph Gap = CompTimeInterpAtEnd - RefTotalTime
                // Drift = TrueGap - GraphGap

                // Since interpolate() is bounded, at maxDist it returns maxTime.
                // However, our loop goes up to RefDistance.
                // If CompDistance < RefDistance, we extrapolate or clamp.

                // For simplicity in this bulletproof version, we stick to raw delta 
                // as the robust interpolation usually handles it well enough for visual check,
                // avoiding over-complex drift logic that causes jumps if data ends early.

                row[`delta_${id}`] = rawDelta;
                row[`time_${id}`] = compTime;
            }
        });

        combinedData.push(row);
    }

    return combinedData;
};

// --- MAIN PIPELINE ---
export const processTelemetryData = (
    inputs: { driver: Driver; data: CarData[]; lapStartDate: string; lapDuration: number; traceId: string }[]
) => {
    // 1. Enrich & Sanitize
    const enrichedInputs = [];
    for (const input of inputs) {
        const result = enrichAndSanitize(input.data, input.lapStartDate, input.lapDuration);
        if (result) {
            enrichedInputs.push({ 
                traceId: input.traceId, 
                processed: result.processed, 
                totalDist: result.totalDist,
                totalTime: result.totalTime
            });
        }
    }

    if (enrichedInputs.length === 0) return [];

    // 2. Resample & Delta
    return buildFastF1Grid(enrichedInputs);
};

import { CarData, Driver } from '../types';

export interface ProcessedCarData extends CarData {
    calculatedDistance: number;
    relativeTime: number; // Seconds from start of lap (strictly 0-based)
}

// --- EXPORTED UTILS ---

export const formatLapTime = (seconds: number): string => {
    if (typeof seconds !== 'number' || isNaN(seconds)) return "0:00.000";
    const m = Math.floor(seconds / 60);
    const s = (seconds % 60).toFixed(3);
    return `${m}:${s.padStart(6, '0')}`;
};

// --- INTERNAL HELPERS ---

/**
 * Robust Linear Interpolation (FastF1 style)
 */
const interpolate = (x: number, xPoints: number[], yPoints: number[]): number => {
    if (xPoints.length === 0) return 0;
    if (x <= xPoints[0]) return yPoints[0];
    const len = xPoints.length;
    if (x >= xPoints[len - 1]) return yPoints[len - 1];

    let low = 0, high = len - 1;
    while (low < high) {
        const mid = (low + high) >>> 1;
        if (xPoints[mid] < x) low = mid + 1;
        else high = mid;
    }

    const i = low > 0 ? low - 1 : 0;
    const x0 = xPoints[i];
    const x1 = xPoints[i + 1];
    const y0 = yPoints[i];
    const y1 = yPoints[i + 1];

    if (x1 - x0 === 0) return y0;

    return y0 + (x - x0) * (y1 - y0) / (x1 - x0);
};

/**
 * STEP 1: Enrich & Sanitize (Monotonicity Check)
 * Calculates Distance via Integration and enforces strictly increasing distance/time.
 */
const enrichAndSanitize = (data: CarData[], lapStartDate: string, lapDuration: number) => {
    const len = data.length;
    if (len === 0) return null;

    // Sort chronologically
    const sortedData = [...data].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const lapStartEpoch = new Date(lapStartDate).getTime();
    const rawPoints = [];

    let cumulativeDist = 0;

    // 1. Integration Loop
    for (let i = 0; i < len; i++) {
        const d = sortedData[i];
        if (i > 0) {
            const prev = sortedData[i-1];
            const timeDelta = (new Date(d.date).getTime() - new Date(prev.date).getTime()) / 1000;
            const vCurrent = d.speed / 3.6; // m/s
            const vPrev = prev.speed / 3.6;

            // Trapezoidal integration
            const distDelta = ((vCurrent + vPrev) / 2) * timeDelta;

            // Physics filter: discard impossible jumps (teleportation) or negative checks
            // 150m/s is approx 540km/h, a safe upper bound for F1
            if (distDelta >= 0 && distDelta < 150) { 
                cumulativeDist += distDelta;
            }
        }

        // Calculate relative time from Lap Start
        const t = (new Date(d.date).getTime() - lapStartEpoch) / 1000;

        // Filter to slightly wider than lap window to ensure interpolation coverage
        if (t >= -2.0 && t <= lapDuration + 2.0) {
            rawPoints.push({ ...d, calculatedDistance: cumulativeDist, relativeTime: t });
        }
    }

    if (rawPoints.length < 10) return null;

    // 2. Monotonicity Enforcement (The "Bulletproof" Step)
    // We only keep points where distance AND time are strictly greater than the previous kept point.
    const cleanPoints: ProcessedCarData[] = [];

    let zeroRefIndex = rawPoints.findIndex(p => p.relativeTime >= 0);
    if (zeroRefIndex === -1) zeroRefIndex = 0;

    const originDist = rawPoints[zeroRefIndex].calculatedDistance;
    const originTime = rawPoints[zeroRefIndex].relativeTime;

    let maxDist = -1;
    let maxTime = -1;

    for (const p of rawPoints) {
        // Normalize
        const relDist = p.calculatedDistance - originDist;
        const relTime = p.relativeTime - originTime;

        // Strict increasing check (epsilon 0.001)
        if (relDist > maxDist + 0.001 && relTime > maxTime + 0.001) {
            maxDist = relDist;
            maxTime = relTime;

            cleanPoints.push({
                ...p,
                calculatedDistance: relDist,
                relativeTime: relTime
            });
        }
    }

    // Ensure we cover the full lap distance approx
    if (cleanPoints.length < 2) return null;

    return {
        processed: cleanPoints,
        totalDist: cleanPoints[cleanPoints.length - 1].calculatedDistance,
        totalTime: cleanPoints[cleanPoints.length - 1].relativeTime
    };
};

/**
 * STEP 2 & 3: Master Axis Resampling & Bias Corrected Delta
 */
const buildFastF1Grid = (
    inputs: { traceId: string; processed: ProcessedCarData[]; totalDist: number; totalTime: number }[]
) => {
    if (inputs.length === 0) return [];

    // 1. Identify Reference (Fastest Lap)
    let refIndex = 0;
    let minTime = Infinity;

    inputs.forEach((input, idx) => {
        const duration = input.totalTime;
        if (duration < minTime) {
            minTime = duration;
            refIndex = idx;
        }
    });

    const refInput = inputs[refIndex];
    const refPoints = refInput.processed;

    // 2. Prepare Interpolation Sources
    const tracesData = inputs.map(input => ({
        id: input.traceId,
        dists: input.processed.map(p => p.calculatedDistance),
        times: input.processed.map(p => p.relativeTime),
        speeds: input.processed.map(p => p.speed),
        rpms: input.processed.map(p => p.rpm),
        gears: input.processed.map(p => p.n_gear),
        throttles: input.processed.map(p => p.throttle),
        brakes: input.processed.map(p => p.brake),
        drs: input.processed.map(p => p.drs),
        // For Bias Correction
        actualTotalTime: input.totalTime
    }));

    const combinedData = [];

    // 3. Iterate over REFERENCE points (Master Axis)
    for (let i = 0; i < refPoints.length; i++) {
        const refP = refPoints[i];
        const dist = refP.calculatedDistance;

        // Limit to positive distance
        if (dist < 0) continue;

        const row: any = { distance: dist };

        tracesData.forEach(trace => {
            const id = trace.id;

            // A. Interpolate Basic Telemetry at Reference Distance
            row[`speed_${id}`] = Math.round(interpolate(dist, trace.dists, trace.speeds));
            row[`rpm_${id}`] = Math.round(interpolate(dist, trace.dists, trace.rpms));
            row[`throttle_${id}`] = Math.round(interpolate(dist, trace.dists, trace.throttles));
            row[`brake_${id}`] = Math.round(interpolate(dist, trace.dists, trace.brakes));

            // Discrete values: Round to nearest
            const gear = interpolate(dist, trace.dists, trace.gears);
            row[`gear_${id}`] = Math.round(gear);
            const drs = interpolate(dist, trace.dists, trace.drs);
            row[`drs_${id}`] = drs > 8 ? 1 : 0;

            // B. Calculate Delta
            if (id === refInput.traceId) {
                row[`delta_${id}`] = 0;
                row[`time_${id}`] = refP.relativeTime;
            } else {
                // 1. Interpolate Comparison Time at this Distance
                const compTime = interpolate(dist, trace.dists, trace.times);
                const refTime = refP.relativeTime;

                // 2. Raw Delta
                const rawDelta = compTime - refTime;

                // 3. Bias Correction (Simple Linear Drift Correction)
                // True Gap = CompTotalTime - RefTotalTime
                // Graph Gap = CompTimeInterpAtEnd - RefTotalTime
                // Drift = TrueGap - GraphGap

                // Use Raw Delta for Bulletproof Monotonicity
                // (Advanced drift correction can be re-enabled if needed, but raw is safest for non-noisy GPS)
                row[`delta_${id}`] = rawDelta;
                row[`time_${id}`] = compTime;
            }
        });

        combinedData.push(row);
    }

    return combinedData;
};

// --- MAIN PIPELINE EXPORT ---

export const processTelemetryData = (
    inputs: { driver: Driver; data: CarData[]; lapStartDate: string; lapDuration: number; traceId: string }[]
) => {
    // 1. Enrich & Sanitize
    const enrichedInputs = [];
    for (const input of inputs) {
        const result = enrichAndSanitize(input.data, input.lapStartDate, input.lapDuration);
        if (result) {
            enrichedInputs.push({ 
                traceId: input.traceId, 
                processed: result.processed, 
                totalDist: result.totalDist,
                totalTime: result.totalTime
            });
        }
    }

    if (enrichedInputs.length === 0) return [];

    // 2. Resample & Delta
    return buildFastF1Grid(enrichedInputs);
};

import React, { useState, useMemo, useRef, useLayoutEffect } from 'react';
import ReactApexChart from 'react-apexcharts';
import { ApexOptions } from 'apexcharts';
import { Lap, Driver, StagedLap } from '../types';
import { generateSeriesColors } from '../utils/teamColors';

interface LapHistoryChartProps {
  selectedDrivers: Driver[];
  lapsData: Map<number, Lap[]>;
  stagedLaps: StagedLap[];
  onToggleLap: (driver: Driver, lap: Lap) => void;
  colors: string[]; 
}

// --- INTERNAL COMPONENT: RESPONSIVE CHART WRAPPER ---
const ResponsiveApexChart: React.FC<{
    options: ApexOptions;
    series: ApexOptions['series'];
    type: "line" | "area" | "bar";
    className?: string;
}> = ({ options, series, type, className }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [shouldRender, setShouldRender] = useState(false);

    useLayoutEffect(() => {
        if (!containerRef.current) return;

        const resizeObserver = new ResizeObserver((entries) => {
            if (!Array.isArray(entries) || !entries.length) return;

            const entry = entries[0];
            const { width, height } = entry.contentRect;

            if (width > 0 && height > 0) {
                requestAnimationFrame(() => {
                    setShouldRender(true);
                });
            }
        });

        resizeObserver.observe(containerRef.current);

        return () => resizeObserver.disconnect();
    }, []);

    return (
        <div ref={containerRef} className={`w-full h-full relative min-h-[50px] ${className || ''}`}>
            {shouldRender ? (
                <ReactApexChart
                    options={options}
                    series={series}
                    type={type}
                    height="100%"
                    width="100%"
                />
            ) : (
                <div className="absolute inset-0 flex items-center justify-center opacity-30">
                     <div className="w-6 h-6 border-2 border-f1-red border-t-transparent rounded-full animate-spin"></div>
                </div>
            )}
        </div>
    );
};

// Utility for formatting time (m:ss.ms)
const formatTime = (val: number) => {
    if (typeof val !== 'number' || isNaN(val) || val <= 0) return '';
    const m = Math.floor(val / 60);
    const s = (val % 60).toFixed(3);
    return `${m}:${s.padStart(6, '0')}`;
};

const LapHistoryChart: React.FC<LapHistoryChartProps> = ({
  selectedDrivers,
  lapsData,
  onToggleLap,
}) => {
  // Local state for visibility toggling
  const [hiddenDrivers, setHiddenDrivers] = useState<Set<number>>(new Set());

  const toggleDriver = (driverNumber: number) => {
      const next = new Set(hiddenDrivers);
      if (next.has(driverNumber)) next.delete(driverNumber);
      else next.add(driverNumber);
      setHiddenDrivers(next);
  };

  // 1. DATA PREPARATION
  const { series, chartColors, activeDrivers } = useMemo(() => {
    if (selectedDrivers.length === 0) {
        return { series: [], chartColors: [], activeDrivers: [] };
    }

    const stableColors = generateSeriesColors(selectedDrivers);

    const activeSeries: any[] = [];
    const activeColors: string[] = [];
    const driversRef: Driver[] = [];

    selectedDrivers.forEach((driver, index) => {
        if (hiddenDrivers.has(driver.driver_number)) return;

        const rawLaps = lapsData.get(driver.driver_number);
        if (!rawLaps || !Array.isArray(rawLaps)) return;

        const cleanData = rawLaps
            .filter(l => {
                const val = l.lap_duration;
                return typeof val === 'number' && !isNaN(val) && val > 0 && val < 600; 
            })
            .sort((a, b) => a.lap_number - b.lap_number)
            .map(l => ({
                x: l.lap_number,
                y: l.lap_duration
            }));

        if (cleanData.length > 0) {
            activeSeries.push({
                name: driver.name_acronym,
                data: cleanData
            });
            activeColors.push(stableColors[index]);
            driversRef.push(driver);
        }
    });

    return { series: activeSeries, chartColors: activeColors, activeDrivers: driversRef };
  }, [selectedDrivers, lapsData, hiddenDrivers]);

  // 2. CHART OPTIONS
  const options: ApexOptions = useMemo(() => ({
      chart: {
          type: 'line', 
          background: 'transparent',
          height: 350,
          toolbar: { show: false }, 
          zoom: { enabled: false }, 
          animations: { enabled: false }, 
          events: {
            markerClick: (event, chartContext, { seriesIndex, dataPointIndex }) => {
                if (!event || !chartContext || !chartContext.w || !chartContext.w.config.series) return;

                const target = event.target as HTMLElement | SVGElement;
                if (target) {
                    target.style.transformBox = 'fill-box';
                    target.style.transformOrigin = 'center';
                    target.style.transition = 'transform 0.1s cubic-bezier(0.175, 0.885, 0.32, 1.275)';

                    requestAnimationFrame(() => {
                        target.style.transform = 'scale(0.8)';
                        setTimeout(() => {
                            target.style.transform = 'scale(1.4)';
                            setTimeout(() => {
                                target.style.transform = 'scale(1)';
                            }, 150);
                        }, 100);
                    });
                }

                const clickedSeries = chartContext.w.config.series[seriesIndex];
                if (!clickedSeries) return;

                const driverName = clickedSeries.name;
                const lapNumber = clickedSeries.data[dataPointIndex]?.x;

                if (lapNumber === undefined) return;

                const driver = activeDrivers.find(d => d.name_acronym === driverName);
                if (driver) {
                    const laps = lapsData.get(driver.driver_number);
                    const lap = laps?.find(l => l.lap_number === lapNumber);
                    if (lap) onToggleLap(driver, lap);
                }
            },
            dataPointMouseEnter: (event) => {
                if (event && event.target) {
                    (event.target as HTMLElement).style.cursor = 'pointer';
                }
            },
            dataPointMouseLeave: (event) => {
                if (event && event.target) {
                    (event.target as HTMLElement).style.cursor = 'default';
                }
            }
          }
      },
      theme: { mode: 'dark' },
      colors: chartColors,
      stroke: {
          curve: 'monotoneCubic', 
          width: 2,
      },
      fill: {
          type: 'solid',
          opacity: 1, 
      },
      grid: {
          borderColor: '#334155',
          strokeDashArray: 3,
          xaxis: { lines: { show: false } },
          yaxis: { lines: { show: true } },
          padding: { 
              top: 10,
              right: 30, 
              bottom: 10,
              left: 20   
          }
      },
      markers: {
          size: 4,
          strokeWidth: 0,
          strokeColors: '#fff',
          hover: { size: 6 }
      },
      xaxis: {
          type: 'numeric',
          title: { text: 'Lap Number', style: { color: '#64748b', fontSize: '10px' } },
          labels: { 
              style: { colors: '#94a3b8', fontFamily: 'JetBrains Mono' },
              formatter: (val) => Math.floor(Number(val)).toString()
          },
          tooltip: { enabled: false },
          axisBorder: { show: false },
          axisTicks: { show: false },
          decimalsInFloat: 0,
      },
      yaxis: {
          labels: {
              style: { colors: '#94a3b8', fontFamily: 'JetBrains Mono' },
              formatter: (val) => formatTime(val),
          },
      },
      legend: { show: false }, 
      tooltip: {
          theme: 'dark',
          shared: true,
          intersect: false,
          followCursor: true,
          y: {
              formatter: (val) => formatTime(val)
          },
          style: {
              fontSize: '12px',
              fontFamily: 'JetBrains Mono'
          }
      },
  }), [chartColors, activeDrivers, lapsData, onToggleLap]);

  // 3. UI RENDER
  if (selectedDrivers.length === 0) {
      return (
        <div className="w-full h-[380px] border-2 border-dashed border-slate-800 rounded-lg flex items-center justify-center bg-transparent mb-6">
            <span className="text-slate-600 font-mono text-xs uppercase tracking-[0.2em] font-medium">
                Waiting for Lap Data...
            </span>
        </div>
      );
  }

  const legendColors = generateSeriesColors(selectedDrivers);

  return (
    <div className="w-full h-[380px] bg-f1-surface border border-white/5 rounded-lg p-5 pb-2 mb-6 shadow-xl relative">

      {/* HEADER */}
      <div className="flex justify-between items-center mb-4 h-6">
          <h3 className="text-xs font-bold uppercase tracking-widest text-f1-muted flex items-center gap-2">
              <span className="w-2 h-2 bg-f1-red rounded-full shadow-[0_0_8px_rgba(255,30,0,0.6)] animate-pulse"></span>
              Lap History Overview
          </h3>

          <div className="flex gap-2">
             {selectedDrivers.map((d, i) => {
                 const isHidden = hiddenDrivers.has(d.driver_number);
                 const color = legendColors[i];
                 return (
                     <button 
                        key={d.driver_number}
                        onClick={() => toggleDriver(d.driver_number)}
                        className={`flex items-center gap-1.5 px-2 py-1 rounded transition-all active:scale-95 duration-200 border border-transparent hover:border-white/10 ${isHidden ? 'opacity-40 grayscale decoration-white/30 line-through' : 'bg-white/5 hover:bg-white/10'}`}
                        title={isHidden ? "Show Driver" : "Hide Driver"}
                     >
                         <span className="w-2 h-2 rounded-full shadow-sm" style={{ backgroundColor: color }}></span>
                         <span className={`text-[10px] font-bold text-gray-300 uppercase ${isHidden ? 'text-f1-muted' : ''}`}>{d.name_acronym}</span>
                     </button>
                 );
             })}
          </div>
      </div>

      {/* CHART CONTAINER - Uses Responsive Wrapper */}
      <div className="flex-1 w-full min-h-0 relative h-[300px]">
         {series.length > 0 ? (
             <ResponsiveApexChart 
                options={options} 
                series={series} 
                type="line" 
             />
         ) : (
            <div className="flex items-center justify-center h-full text-f1-muted text-xs uppercase tracking-widest">
                All drivers hidden
            </div>
         )}
      </div>
      <div className="absolute bottom-4 right-6 text-[9px] text-f1-muted uppercase tracking-widest opacity-50 pointer-events-none">
        Click point to compare telemetry
      </div>
    </div>
  );
};

export default React.memo(LapHistoryChart);

import React, { useState, useMemo, useRef, useLayoutEffect } from 'react';
import ReactApexChart from 'react-apexcharts';
import { ApexOptions } from 'apexcharts';
import { motion, AnimatePresence } from 'framer-motion';
import { TelemetryPoint, StagedLap } from '../types';
import { generateSeriesColors } from '../utils/teamColors';

// --- INTERNAL COMPONENT: RESPONSIVE CHART WRAPPER ---
// Encapsulates the ResizeObserver logic to ensure ApexCharts only renders
// when the parent container has valid dimensions.
const ResponsiveApexChart: React.FC<{
    options: ApexOptions;
    series: ApexOptions['series'];
    type: "line" | "area" | "bar";
    className?: string;
}> = ({ options, series, type, className }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [shouldRender, setShouldRender] = useState(false);

    useLayoutEffect(() => {
        if (!containerRef.current) return;

        const resizeObserver = new ResizeObserver((entries) => {
            if (!Array.isArray(entries) || !entries.length) return;

            const entry = entries[0];
            const { width, height } = entry.contentRect;

            // Only trigger render if dimensions are valid
            if (width > 0 && height > 0) {
                // Use requestAnimationFrame to prevent "ResizeObserver loop limit exceeded"
                requestAnimationFrame(() => {
                    setShouldRender(true);
                });
            }
        });

        resizeObserver.observe(containerRef.current);

        return () => resizeObserver.disconnect();
    }, []);

    return (
        <div ref={containerRef} className={`w-full h-full relative min-h-[50px] ${className || ''}`}>
            {shouldRender ? (
                <ReactApexChart
                    options={options}
                    series={series}
                    type={type}
                    height="100%"
                    width="100%"
                />
            ) : (
                // Optional: Subtle skeleton/loading state while calculating layout
                <div className="absolute inset-0 flex items-center justify-center opacity-30">
                     <div className="w-6 h-6 border-2 border-f1-red border-t-transparent rounded-full animate-spin"></div>
                </div>
            )}
        </div>
    );
};

