      yaxis: {
          labels: {
              style: { colors: '#94a3b8', fontSize: '11px', fontFamily: 'JetBrains Mono, monospace' },
              formatter: (val) => Math.round(Number(val)).toString(),
          },
      },
      markers: {
          size: 0,
          hover: { size: 5, strokeWidth: 0, strokeColors: '#fff' }
      },
      legend: { show: false }, 
      tooltip: {
          theme: 'dark',
          style: { fontSize: '12px', fontFamily: 'JetBrains Mono, monospace' },
          x: { formatter: (val) => `${Math.round(Number(val))}m` },
          y: { 
              formatter: (val) => {
                  const numVal = Number(val);
                  if (dataKey === 'speed') return `${Math.round(numVal)} km/h`;
                  if (dataKey === 'rpm') return `${Math.round(numVal)}`;
                  if (dataKey === 'gear') return `${numVal}`;
                  return `${Math.round(numVal)}%`;
              } 
          }
      }
  }), [chartColors, dataKey, isExpanded]);

  const toggleVisibility = (index: number) => {
      const next = new Set(hiddenIndices);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      setHiddenIndices(next);
  };

  if (!data || data.length === 0) return null;

  return (
    <>
      <div className="relative w-full h-[320px] bg-f1-surface border border-white/5 rounded-lg p-4 flex flex-col mb-6 hover:border-white/10 transition-colors shadow-lg group/chart">

        {/* HEADER */}
        <div className="flex justify-between items-center mb-2 shrink-0 h-8">
            <div className="flex items-center gap-2">
                 <button 
                    onClick={() => setIsExpanded(true)}
                    className="p-1.5 rounded hover:bg-white/10 text-f1-muted hover:text-white transition-colors active:scale-95"
                    title="Expand Chart"
                >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                    </svg>
                </button>
                <h3 className="text-xs font-bold uppercase tracking-widest text-f1-muted px-1">
                    {title}
                </h3>
            </div>

            <div className="flex flex-wrap gap-2">
                {stagedLaps.map((sl, index) => {
                    const isHidden = hiddenIndices.has(index);
                    const color = allColors[index];
                    return (
                        <button 
                            key={sl.id} 
                            onClick={(e) => { e.stopPropagation(); toggleVisibility(index); }}
                            className={`flex items-center gap-2 px-2 py-1 rounded border border-transparent text-[10px] font-medium transition-all active:scale-95 duration-100 ${isHidden ? 'opacity-40 grayscale bg-transparent line-through text-f1-muted' : 'bg-white/5 hover:bg-white/10 text-f1-text'}`}
                        >
                            <span className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></span>
                            <span className="uppercase">{sl.driver.name_acronym} (L{sl.lap.lap_number})</span>
                        </button>
                    );
                })}
            </div>
        </div>

        {/* CHART CONTAINER - Uses Responsive Wrapper */}
        <div className="flex-1 w-full min-h-0 relative">
            <ResponsiveApexChart 
                options={options}
                series={series}
                type="line"
            />
        </div>
      </div>

      {/* FULLSCREEN MODAL */}
      <AnimatePresence>
        {isExpanded && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
                <motion.div 
                    initial={{ opacity: 0 }} 
                    animate={{ opacity: 1 }} 
                    exit={{ opacity: 0 }}
                    onClick={() => setIsExpanded(false)}
                    className="absolute inset-0 bg-black/90 backdrop-blur-sm"
                />

                <motion.div 
                    initial={{ scale: 0.95, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    exit={{ scale: 0.95, opacity: 0 }}
                    transition={{ duration: 0.2 }}
                    className="relative w-full max-w-7xl h-[85vh] bg-[#0F1014] border border-f1-border rounded-xl p-6 shadow-2xl flex flex-col"
                >
                     <div className="flex justify-between items-center mb-6 shrink-0">
                        <div>
                             <h3 className="text-lg font-bold uppercase tracking-widest text-white">
                                {title} Analysis
                            </h3>
                             <div className="flex flex-wrap gap-3 mt-2">
                                {stagedLaps.map((sl, index) => {
                                    const isHidden = hiddenIndices.has(index);
                                    const color = allColors[index];
                                    return (
                                        <button 
                                            key={sl.id} 
                                            onClick={() => toggleVisibility(index)}
                                            className={`flex items-center gap-2 px-3 py-1.5 rounded transition-all active:scale-95 ${isHidden ? 'opacity-40 bg-white/5 line-through' : 'bg-white/10 ring-1 ring-white/10'}`}
                                        >
                                            <span className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></span>
                                            <span className="text-xs font-bold text-white uppercase">{sl.driver.name_acronym} (L{sl.lap.lap_number})</span>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                        <button 
                            onClick={() => setIsExpanded(false)}
                            className="p-3 bg-white/5 hover:bg-white/10 hover:text-white text-f1-muted rounded-full transition-all active:scale-95"
                        >
                            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                            </svg>
                        </button>
                    </div>

                    <div className="flex-1 w-full min-h-0 bg-[#0B0B0F] rounded-lg p-2 border border-white/5">
                        {/* 
                            RESPOINSIVE WRAPPER IN MODAL
                            Crucial here because Framer Motion animates from scale 0.95/opacity 0.
                            The Observer waits for valid dimensions before rendering.
                         */}
                         <ResponsiveApexChart 
                            options={options}
                            series={series}
                            type="line"
                         />
                    </div>
                </motion.div>
            </div>
        )}
      </AnimatePresence>
    </>
  );
};

export default React.memo(TelemetrySingleChart);

payload.text:
Agisci come un Senior F1 Data Engineer e React Developer.

Voglio implementare da zero il grafico dell'**Analisi Delta (Gap al Reference)**, utilizzando l'algoritmo standard del settore (simile alla libreria Python FastF1).

Devi modificare due file: `utils/telemetryUtils.ts` e `App.tsx`.

### 1. LOGICA MATEMATICA (`utils/telemetryUtils.ts`)
Dobbiamo esportare una funzione `calculateDelta(refLap, compLap)`.
Poiché i dati GPS grezzi sono rumorosi, la funzione deve seguire rigorosamente questi passaggi per evitare grafici errati:

1.  **Sort & Sanitize:**
    * Ordina i dati in ingresso per `date`.
    * **Force Zeroing:** Sottrai a tutti i punti il tempo e la distanza del *primo* punto, in modo che entrambi i giri inizino esattamente a coordinate (0m, 0s).
    * **Monotonicity Check:** Filtra l'array mantenendo solo i punti dove la `lap_distance` è strettamente maggiore della precedente. Questo rimuove il rumore del GPS ed evita che l'interpolazione fallisca.

2.  **Resampling (Interpolazione):**
    * Usa le distanze del "Reference Lap" come asse X.
    * Per ogni metro del Reference, calcola il tempo del Comparison Lap usando l'interpolazione lineare.
    * `Delta_Grezzo = Tempo_Interpolato_Comparison - Tempo_Reference`.

3.  **Bias Correction (Drift Fix):**
    * Calcola il distacco reale sul traguardo: `True_Gap = TotalTime_Comp - TotalTime_Ref`.
    * Calcola il distacco finale del grafico: `Graph_Gap = Delta_Grezzo[last]`.
    * Calcola il Drift: `Diff = True_Gap - Graph_Gap`.
    * Applica una correzione lineare progressiva: `Delta_Finale = Delta_Grezzo + (Diff * (Dist / TotalDist))`.
    * Questo garantisce matematicamente che il grafico finisca nel punto corretto.

**Ecco il codice ESATTO che voglio tu usi per `utils/telemetryUtils.ts` (non inventare altro):**

```typescript
function interp(x: number, xp: number[], fp: number[]): number {
  if (xp.length === 0) return 0;
  if (x <= xp[0]) return fp[0];
  if (x >= xp[xp.length - 1]) return fp[fp.length - 1];
  let i = 0; while (xp[i + 1] < x) i++;
  const x0 = xp[i], x1 = xp[i + 1], y0 = fp[i], y1 = fp[i + 1];
  if (x1 === x0) return y0;
  return y0 + (x - x0) * (y1 - y0) / (x1 - x0);
}

export const calculateDelta = (refLapRaw: any[], compLapRaw: any[]) => {
  // 1. Prepare Data
  const process = (data: any[]) => {
    if (!data || data.length < 2) return null;
    const sorted = [...data].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    // Convert dates to relative seconds
    const startT = new Date(sorted[0].date).getTime();
    const rawPoints = sorted.map(p => ({
      d: typeof p.lap_distance === 'number' ? p.lap_distance : 0,
      t: (new Date(p.date).getTime() - startT) / 1000
    }));

    // Zeroing & Monotonicity
    const cleanD: number[] = [0]; // Force start 0
    const cleanT: number[] = [0]; // Force start 0
    let maxD = 0;
    const offsetD = rawPoints[0].d; 

    rawPoints.forEach(p => {
      const normD = p.d - offsetD; // Normalize distance start
      const normT = p.t;           // Time is already relative to start
      if (normD > maxD && normD > 0) {
        maxD = normD;
        cleanD.push(normD);
        cleanT.push(normT);
      }
    });
    return { d: cleanD, t: cleanT };
  };

  const ref = process(refLapRaw);
  const comp = process(compLapRaw);
  if (!ref || !comp) return [];

  // 2. Resampling & Raw Delta
  const maxCommonDist = Math.min(ref.d[ref.d.length-1], comp.d[comp.d.length-1]);
  // Create fixed grid every 5m or use ref points
  const gridPoints = ref.d.filter(d => d <= maxCommonDist);

  const rawData = gridPoints.map(dist => {
    const tRef = interp(dist, ref.d, ref.t);
    const tComp = interp(dist, comp.d, comp.t);
    return { x: dist, delta: tComp - tRef };
  });

  // 3. Drift Correction
  const trueGap = comp.t[comp.t.length-1] - ref.t[ref.t.length-1];
  const graphGap = rawData[rawData.length-1].delta;
  const drift = trueGap - graphGap;

  return rawData.map(p => ({
    x: p.x,
    y: p.delta + (drift * (p.x / maxCommonDist))
  }));
};

2. UI INTEGRATION (App.tsx)
Aggiungi il grafico Delta alla griglia delle telemetrie.

Logica Reference: Il "Reference Lap" deve essere automaticamente il giro più veloce tra i piloti selezionati (selectedDrivers). Tutti gli altri piloti mostreranno il delta rispetto a lui.

Posizione: Aggiungilo come prima o seconda card nella griglia telemetrica (es. larghezza piena o accanto allo Speed).

Props: Passa data={telemetryData} e selectedDrivers.

Memo: Usa useMemo per chiamare calculateDelta solo quando i dati cambiano.

Visualizzazione:

Reference Driver: Linea piatta a 0 (puoi anche non disegnarla, basta disegnare gli altri).

Altri Driver: Le linee generate da calculateDelta.

Usa colori coerenti coi team.

Asse Y formatter: val => (val > 0 ? '+' : '') + val.toFixed(3) + 's'.

Output: Genera il codice completo per utils/telemetryUtils.ts (con la funzione fornita) e le parti rilevanti di App.tsx per mostrare il grafico.
